-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[58097] = { id = 58097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from the Uldum Accord", description = "The Uldum Accord appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", completion = "The accord is standing strong in the face of this threat. All of Azeroth is in your debt for the heroic efforts you are making. \n\nThank you champion!", objectives = "Speak with Provisioner Qorra in Uldum for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58103] = { id = 58103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride or Unit", description = "I hope that working with my phalynx has swayed you, {name}.\n\nLet us meet with Nemea. There you can decide whose way of life is superior, and which you would prefer to pursue.", progress = "Surely you must agree that the ease of phalynx companionship suits you.", completion = "It is done.", objectives = "Meet with Pelodis and Nemea, then pick a side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58104] = { id = 58104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show, Don't Tell", description = "As a new champion of the Court, you'll need to be properly introduced to the rest of the Night Fae. And that calls for something big. Bold. Memorable. A demonstration of who you are and where you've come from. Something with... flair.\n\nNormally, we spend ages crafting a masterpiece presentation. But we don't have time for that! We'll just have to improvise.\n\n<Moonberry winks.>\n\nCommune with me so I can pick up the highlights! I'll make sure it's a show to remember!", completion = "Oh good! You're here! No time to rehearse, but that shouldn't be too much of a problem.", objectives = "Commune with Lady Moonberry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58122] = { id = 58122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Horde", description = "What an adventure, {class}!\n\nThere is so much to explore... so much to discover. These are such exciting times!\n\nWe'll show our allies in the Horde the value of having some clever Vulpera around.\n\nPlease meet with the ambassador at the Orgrimmar embassy. \n\nI'll meet you there, {name}!", completion = "Are you the new one? I'm supposed to welcome you.\n\n<Blackguard lets out an exasperated sigh.>", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58124] = { id = 58124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", progress = "This city is huge!", completion = "So many options for you!\n\nAnd by you, I mean us. I bet there are some fascinating curiosities to be found...\n\nBe careful out there!", objectives = "Talk to Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58127] = { id = 58127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Sinstone", progress = "With my archives, it shouldn't be too challenging to identify and recreate the sinstone of an inquisitor.", completion = "A strong Maw Walker like yourself should have no problem taking down an inquisitor.\n\nHappy hunting." }
quests[58128] = { id = 58128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Inquisitor Sinstone", progress = "Even with my archives, it could be difficult to identify and recreate the sinstone of a high inquisitor.", completion = "High Inquisitors are powerful enemies. Bring a friend or two if you plan on challenging one directly.\n\nHappy hunting." }
quests[58129] = { id = 58129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Inquisitor Sinstone", progress = "The Grand Inquisitors are incredibly protective of their secrets. We will need to expend exceptional resources to identify and recreate one of their sinstones.", completion = "Grand Inquisitors Nicu and Aurica are the most powerful venthyr walking these halls, Maw Walker.\n\nDo not face them alone. Bring allies. Lots of them." }
quests[58144] = { id = 58144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battered and Bruised" }
quests[58146] = { id = 58146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Alliance", description = "As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance!\n\nA world of adventure awaits you beyond the walls of Mechagon City.\n\nWhen you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy.\n\nThere will be many potential avenues of advancement available to you.\n\nChoose wisely, improve, and remember to share your data.", progress = "Welcome to Stormwind, {race}.", completion = "Ah, there you are, {name}! We've been inspecting--err--expecting you!", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58147] = { id = 58147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {class}. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", progress = "So, how does Stormwind suit you?", completion = "You will be an excellent representative of what it means to be a {race}.\n\nStay shiny out there, friend.", objectives = "Find Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58151] = { id = 58151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of N'Zoth", description = "The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers.\n\nSomething must be done.\n\nEnter the darkness, {name}, and strike down the enemy.", progress = "The winds envelop us, comforting, calming... but beneath it all lurks a great, ever-present darkness.", completion = "Your work will not go unnoticed. Of that, I am certain.", objectives = "Defeat 20 minions of N'Zoth within the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58155] = { id = 58155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hand in the Dark", description = "Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself.\n\nThoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation.\n\nSo many are lost to the darkness, unable to resist these temptations, but not all.\n\nDo what you can to preserve those that fight against the darkness. We mustn't allow them to fall.", progress = "It is best not to linger in darkness.", completion = "The withering whispers lie in wait. Remain vigilant, {name}.", objectives = "Rescue 8 souls from the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58156] = { id = 58156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquishing the Darkness", description = "The darkness grows. The cycle continues.\n\nDo what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.", progress = "We both know what must be done.", completion = "Your dedication to stemming the corruption remains invaluable, {name}.", objectives = "Repel N'Zoth's corruption within the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58157] = { id = 58157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break a Leg", description = "The show is about to begin! You... that's what you're going to wear? Well, I suppose it works.\n\nFor your grand introduction, we will re-enact recent victories and events that took place on Azzinoth. Er, Azeroth. That's where you're from, right?\n\nThe Starlight Company has graciously volunteered to assist us in this production. We've recruited some special guests as well! \n\nDon't worry about the script. This is your story, after all!\n\nJust try not to get too much blood on stage. It's hard to clean.", progress = "Well, that wasn't... terrible.", completion = "Not bad! Not great, but not bad. Quickly now, we'll need to help set the stage for the next act!", objectives = "Reenact the Third Invasion of the Legion on Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58158] = { id = 58158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fourth Wall, er, War", description = "It's time for the next act of your theatrical introduction: the Grand Drama Of Azereth!\n\nAzeroth. Right. All these worlds are hard to tell apart.\n\nHelp set the stage, then come back here. You'll need to play a few other characters before you appear as yourself again.\n\nGet a move on! We have a lot to cover!", progress = "Come on, come on! We have a crowd to please!", completion = "I can honestly say I have never seen a performance quite like this.\n\nNow... On to our grand finale! A battle for your world that is certain to make the court sit up and take notice!", objectives = "Set the Stage then help the reenactment of events after the Legion's fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58159] = { id = 58159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's My Motivation?", description = "Now for our finale! A thrilling performance of the most recent trials on Azathoth!\n\n<Featherlight checks his notes.>\n\nAzeroth. Whatever. It features an artificial god, a powerful magic ice princess, an infamous queen, and an eldritch abomination of unspeakable terror! Who doesn't love a good drama with a dash of existential horror?\n\nYou're back to playing yourself, so just... do whatever heroes are supposed to do!", progress = "Well! That was exciting.", completion = "A fair enough performance! \n\nI think everyone's more acquainted with your world and the role you've played within it.\n\nNext time, the set design will be a bit more... prepared. But for now...\n\n<Moonberry nods at Ysera.>\n\nI think your friend wishes to have a word. Don't take too long. We still have to hold the final induction ceremony at the Heart of the Forest.", objectives = "Perform the final acts!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58160] = { id = 58160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Queen and Grove!", description = "A stunning performance... in more ways than one.\n\nSo much has transpired on Azeroth in my absence. But there was one dream I did not see portrayed onstage.\n\nI dreamt of Tyrande, engulfed in darkness, twisted by anger and a thirst for vengeance. I witnessed a forbidden ritual, the rise of a new Night Warrior, and a hunt that can end only in tragedy. That too must be real.\n\n<Ysera shakes her head.>\n\nThe Winter Queen awaits you in the Heart of the Forest. We had best be on our way.", progress = "Welcome to the Hunt.", completion = "Your actions here will echo beyond the veil. Aid the forest, and all mortal worlds may yet be saved.", objectives = "Travel with Ysera back to the Heart Tree to join the Covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58161] = { id = 58161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forest Disappearances", description = "A moment of your time, friend?\n\nA short while ago a sylvar named Partik came seeking the aid of our grove. He said his village was under attack by the gorm and was in danger of crumbling away altogether. I told him we could not spare any soldiers, but their people were welcome to take refuge with us.\n\nHowever, it has been some time since he left and I have not seen or heard anyone from that region since.\n\nCan you go investigate? He came from the northeast.", completion = "No, no... what is happening!?", objectives = "Find Partik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58162] = { id = 58162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Masks", description = "The village, my friends, gone. They are no more.\n\nI came back from the nearby grove to find them... like this. Even Lavrash, my best friend! He came at me with only violence in his heart.\n\nThey are all wearing these masks now, and they are not themselves anymore.\n\nPlease, deliver them from this fate. Bring me their masks and perhaps we can decipher this mystery.", progress = "For so many to fall, I did not think I was gone that long....", completion = "These masks must contain some secret to the possession.", objectives = "Collect 15 Featureless Masks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58163] = { id = 58163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Solution", description = "<A well-made, if well-worn, journal catches your eye.\n\nThumbing through the pages, it is clear that this journal once belonged to someone prominent from this group of night fae. The last few pages are torn out of the book.\n\nPerhaps if the rest of the pages were located then Partik could help decipher what happened here.>", progress = "What's that you've got there?", completion = "<Partik quickly reads over the last few pages. His face turns pale.>", objectives = "Find the missing journal pages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58164] = { id = 58164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cult of Personality", description = "Some of my people are still alive! We must rescue them!\n\nThe prisoners are kept in cages throughout the ridge, waiting for this horrible fate to befall them.\n\nPlease, set them free. We cannot let what happened to Lavrash happen to them!", completion = "So few.... But each one is one more friend we can bring to bear against this madness!", objectives = "Rescue 8 trapped night fae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58165] = { id = 58165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut the Roots", description = "It's just as I feared, friend. The entire village is turned, just like Lavrash.\n\nLewor would have transformed the other elders as soon as possible. They are all strong in their own right. Brave Fiona, clever Bitterfly....\n\nIt pains me to say this, but they must be destroyed. For the good of Ardenweald and the forest, slay our former leaders before they can infect the rest of the land!", progress = "If they fell, then what hope do we have?", completion = "<Partik gulps and turns pale.>\n\nThat's all of them, then? Good.", objectives = "Slay Bitterfly, Fiona Bleakthorn, and Wildtwister Lewor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58166] = { id = 58166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unknown Assailants", description = "This must be the stone he found. I do not recognize the mark.\n\nYou should bring this to the nearby droman. They are wise and retain much of the knowledge of the forests and the realms beyond. They will know what to do.", completion = "What rustles you so, young one?", objectives = "Bring the Strange Runestone to Droman Tashmur in Tirna Vaal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58167] = { id = 58167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventative Measures", description = "Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach.\n\nMake your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.", progress = "Darkness lurks beneath the waters.", completion = "A brief reprieve to catch our breath. Let us hope it lasts.", objectives = "Destroy 3 Void Portals within the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58168] = { id = 58168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark, Glaring Reality", description = "Their eyes are upon us, {name}, watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking.\n\nThe fault is by no means your own. We should have suspected this was the case long ago.\n\nIf we are to continue our efforts with meaningful expectations we must go undetected.\n\nOur old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.", progress = "Seeing things more clearly?", completion = "Keep your eyes open, {name}.", objectives = "Defeat 6 Darkglare Watchers within the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58174] = { id = 58174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All An Aspirant Can Do", description = "I think we can agree that such a reply feels... somewhat hollow.\n\nI choose to take faith that we have done all we can. All of us. I do not know what comes next, but perhaps the path will reveal itself. In the meantime, Pelagos and I will return to Aspirant's Rest for a moment of respite.\n\nWe will meet you there, though there is no need to hurry.", completion = "<Kleia smiles warmly at you.>\n\nDoes this mean you intend to stay?", objectives = "Return to Aspirant's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58175] = { id = 58175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Forge", description = "The Forgelite Prime has taken up the mantle of building our new Crest of Ascension.\n\nNo ordinary tools or materials will do. He will require Phaestus, Genesis of Aeons, Hammer of the First Forgelite. It sits at the shrine to the First Forgelite in the Eternal Forge.\n\nThe Forsworn have taken over this forge to create their own endless centurion army. You must meet Mikanikos at the forge, push back the Forsworn, and retrieve Phaestus for our own uses.", completion = "{name}! Can you believe what the Forsworn have done to my forge?\n\nMust find Phaestus and halt their operation!", objectives = "Meet Mikanikos at the Eternal Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58176] = { id = 58176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stewards of a Feather", description = "You! Maw Walker!\n\nThe forge was bustling. Many forgehands, on task!\n\nThen Forsworn came. Some followed their demands, turned to their side.\n\nBut not all! Yes, rescue forgehands so they can aid us. Work to be done!", progress = "I tried to save, but am no hero. Can only try to organize chaos.", completion = "You did it! Many forgehands return today. Maybe one day the rest return too?\n\nWe will help.", objectives = "Free 5 Captured Forgehands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58177] = { id = 58177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refining Ego", description = "I will locate Phaestus. In the meantime, task for you!\n\nThe Forsworn use my forge to make their centurion army. Their vile intentions warp the metals we use!\n\nDestroy their centurions, take their parts. Smelt them down in the forge to purify the metals, then return to me.\n\nI need much metal for my plan.", progress = "I keep my resources here. The Forsworn stole from me! I cannot let this stand.", completion = "We shall use this metal for many purposes. For the Crest, and for my goliath!", objectives = "Collect 8 Purified Metal by collecting Tainted Centurion Components from centurion units and smelting them down at the Eternal Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58178] = { id = 58178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Partner for Eternity", description = "Before returning to the Hold, one more thing to do.\n\nDefeat the Forsworn and their centurion army!\n\nThis goliath here can help with just that. My finest creation yet!\n\nI need an extra pair of hands. Yours will do.", progress = "Trust he is no ordinary goliath. An extension of my hand itself!", completion = "A partner that embodies my inner strength.\n\nA worthy centurion indeed!", objectives = "Help Mikanikos finish his finest creation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58179] = { id = 58179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instruments of Perfection", description = "Mikanikos is no ordinary steward. He is wise! Talented! The smartest of us all!\n\nAlso very particular!\n\nHe cannot work without his tools. The Forsworn scattered them around the forge!\n\nYou need to rebuild Crest? Retrieve his tools!", progress = "I cannot work in these conditions.", completion = "Sika sent you to retrieve my tools?\n\nShe knows what I need to be productive.", objectives = "Collect Mikanikos's Soulsteel Clamps, Sparkling Driftglobe Core, and Gracepetal Incense Burner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58180] = { id = 58180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phaestus, Genesis of Aeons", description = "Sika reports the Forsworn are widespread. They not only took over production, but the rise as well!\n\nThey organize their armies from the cliffs, send word back to their leaders.\n\nThey've ransacked our shrine to the First Forgelite and took her hammer. My hammer!\n\nDefeat their commander, retrieve Phaestus. You must go now!", progress = "Without Phaestus, we cannot work on the Crest.", completion = "Phaestus returns! Glorious day.\n\nMany thanks, friend. This hammer has been passed down for eons! It belongs in my masterful hands.", objectives = "Collect Phaestus, Genesis of Aeons from Overseer Atticus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58181] = { id = 58181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building the Base", description = "The Crest is almost complete.\n\nI give you the honor of the final touch.\n\nYou have done much. Please, take Phaestus and give the final blow!", progress = "Please care. Phaestus is older than you could dream!", completion = "Perfection!\n\nIt is beautiful, yes? Not done yet, but much work led to great reward.", objectives = "Complete the Crest of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58182] = { id = 58182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dismantling the Opposition", description = "The Forsworn mobilize!\n\nWe cannot allow them to march.\n\nAttune to Bron, share your power with him.\n\nBetween the three of us, we shall destroy this new centurion army!", progress = "Bron was not meant as a tool of destruction, but will excel at it with you!", completion = "Exhilarating! Bron grows stronger with your power.", objectives = "Ride Bron, then defeat 30 Forsworn forces and dismantle 2 Colossus in the Eternal Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58183] = { id = 58183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend to the Forgelite", description = "With Phaestus in hand, we can start building Crest.\n\nLet us return to Elysian Hold. Triumphant!", completion = "Mikanikos returned not long ago with his new centurion. Quite the unique unit.\n\nOf course, the return of Phaestus to kyrian hands is good news indeed. The Archon will be pleased.", objectives = "Return to Polemarch Adrestes in Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58184] = { id = 58184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antiquated Methodology", description = "You possess the correct mindset for retraining a phalynx. I believe you could find great success here.\n\nBefore you commit, I implore you to go across the hill and introduce yourself to my rival, Nemea. She believes that her unreasonable, free-willed larions are better partners than my perfect phalynx.\n\nExperience her lifestyle so that you may know how much greater my work is.", completion = "Pelodis sent you, did he?\n\nSure his phalynx follow orders, but where is their depth?", objectives = "Talk to Nemea at Nemea's Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58185] = { id = 58185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Success Without Soul", description = "The larions seem to truly enjoy your company, Andira most of all.\n\nI hope you've come to understand and appreciate the nuance of working with a beast with free will.\n\nNow you must spend time with Pelodis, down the hill. His phalynx may be effective, but working with them only brings hollow satisfaction.\n\nI am sure working with the phalynx will only strengthen your appreciation of larions.", completion = "I understand you met with Nemea first.\n\nTake solace in the fact that you will not be working with crazed beasts here.", objectives = "Talk to Pelodis at Forgefire Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58207] = { id = 58207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buggin' Out" }
quests[58208] = { id = 58208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brace for Impact", description = "That's it for warming up. You and the other new recruits are a promising bunch, I'll tell you that much.\n\nHold on... what's that sound? I think something big is headed our way!", completion = "This ship may not make it to the island.\n\nHold on to something sturdy and stick with your fellow recruits. We'll get through this.", objectives = "Find Lady Jaina Proudmoore inside the ship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58209] = { id = 58209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand Your Ground", description = "I hope this rain isn't a bad omen... this is supposed to be a simple rescue mission.\n\nYou'll be sparring with me today. We have to make sure you can handle yourself once we make landfall.\n\nLet's see what you've got!", progress = "Having trouble? Happens to the best of us. Just stay calm, select your target, and use one of your abilities on it.\n\nMake sure your target is in front of you. We don't want another incident like when Bjorn tried to throw an axe over his shoulder.", completion = "You're a skilled {class}, recruit. I think you'll prove a welcome addition to the main rescue team.", objectives = "Spar with Private Cole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58211] = { id = 58211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pumped Up", description = "When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up!\n\nTake this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there!\n\nJust be careful with whatever you pull up! You could face some resistance.", progress = "Have you recovered anything useful?", completion = "You love to see it!", objectives = "Collect 15 Salvaged Gear by using the Sludge Pump near bubbling sludge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58214] = { id = 58214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Care", description = "Excellent timing, {name}.\n\nKelsey Steelspark has been sending communications to the capital cities looking for aid.\n\nMekkatorque's condition is quite dire and time is of the essence.\n\nHurry to Boralus Harbor, she will be watching for you.", completion = "You are just in time.", objectives = "Find Kelsey Steelspark in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58216] = { id = 58216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58221] = { id = 58221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gettin' Even" }
quests[58229] = { id = 58229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rallying Cry", description = "Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers.\n\nOur forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale.\n\nFind the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.", completion = "My men will look to your victories this day to bolster their spirits. \n\nRamkahen owes you a debt, {class}.", objectives = "Kill 3 rare minions of N'Zoth in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58230] = { id = 58230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind the Eyes", description = "Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance.\n\nThe eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.", progress = "Is it done?", completion = "The eyes are closed, and my clairvoyance returns.\n\nThank you, {class}.", objectives = "Kill 6 Foul Observers in the Akhenet Fields in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58231] = { id = 58231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom From Madness", description = "In my visions I hear... voices...\n\nTheir words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word.\n\nWe will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.", progress = "Have you found the writings?", completion = "As I suspected, the writings of the cultists appears to be completely incoherent.\n\nLet us hope some truth lies within this madness.", objectives = "Collect 10 Maddened Writings from Black Empire Cultists in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58232] = { id = 58232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Order Among Chaos", description = "It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited.\n\nHowever, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. \n\nI have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.", completion = "A decisive strike against their commanders should buy us some time.\n\nThank you, {class}.", objectives = "Kill 6 faceless minions of N'Zoth in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58233] = { id = 58233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Corruptors", description = "While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. \n\nLike a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form.\n\nThey must be eradicated.", completion = "Uldum breathes a sigh of relief with each twisted manifestation of N'Zoth slain.", objectives = "Kill 10 fleshbeasts in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58234] = { id = 58234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questionable Sourcing", description = "My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health.\n\nI have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption.\n\nIf you could retrieve some samples of this for me, it could prove invaluable in our efforts.", progress = "Have you acquired the reagent?", completion = "You've returned with the samples? Excellent.\n\nLet us hope this has the intended effect.", objectives = "Collect 8 Coalesced Corruption from slimes in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58235] = { id = 58235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anchors of the Black Empire", description = "This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from.\n\nHowever, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces.\n\nIf we truly wish to stem the tide of this invasion, we must destroy the obelisks.", completion = "While the threat has far from subsided, it is comforting to know that our enemy's reinforcements have been slowed. \n\nWe may just survive to see an end to this battle.", objectives = "Destroy 6 Black Empire Obelisks in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58236] = { id = 58236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbolic Destruction", description = "The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. \n\nTheir mindless followers flock to these banners, worshipping them as unholy idols.\n\nBurn them down, and cleanse their taint from our lands.", completion = "Good. It will be a fine day when these disgraceful sigils no longer befoul our land.", objectives = "Destroy 6 Banners of the Black Empire in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58237] = { id = 58237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Uldum", description = "Every moment that N'Zoth's forces remain in Uldum, his corruption seeps further into the land itself.\n\nEven if we were to drive back his minions, the damage he has done to Uldum may be irreversible. \n\nWe must seek out his corruption where it festers and eliminate it.", progress = "We must put a stop to N'Zoth's Corruption.", completion = "Even now, I sense N'Zoth's corruption waning.\n\nYou have done well.", objectives = "Destroy 6 Corruption Tumors in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58238] = { id = 58238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and Tormented", description = "Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. \n\nOur brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions.\n\nI know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.", completion = "Our citizens owe you a debt they may never be able to repay, {name}.\n\nRamkahen thanks you for this service.", objectives = "Free 6 Ramkahen Citizens from Torment Cells within the Lost City of Tol'vir in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58239] = { id = 58239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in Brigandry", description = "The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days.\n\nOne such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them.\n\nFind their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.", progress = "Found anything worthwhile?", completion = "I hope you found what you were looking for.\n\nWe can use all the help we can get in this fight.", objectives = "Loot 3 Black Empire Caches in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58256] = { id = 58256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58257] = { id = 58257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58258] = { id = 58258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58260] = { id = 58260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queens And Future Kings", description = "A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage.\n\nWith Twigin's help, eliminate the queens and recover larvae from the eggs.\n\nI have a plan for the larvae that may allow us to use the marrowbore to our advantage.", progress = "It's dirty work, but we need those larvae.", completion = "Now to put these to a useful purpose.", objectives = "Slay 1 marrowbore queens, and collect 5 marrowbore larvae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58264] = { id = 58264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake Up, Get Up, Get Out There", description = "They need your help!\n\nNot all of the faeries have been turned yet. Some remain prisoner, but they have these masks on their faces....\n\nYou've got to help them! I'm not strong enough to pry off the masks, but you could! You could stop the guards from getting us too!", completion = "You saved my friends!\n\n<Primrose gives you a small grin.>\n\nWe... we make a pretty good team, huh?", objectives = "Aid 8 subdued faeries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58265] = { id = 58265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blooming Villains", description = "Something stinks, traveler. The air to the west is rotten with malice.\n\nShimmerbough has long been a peaceful way station along the Path of Rebirth. The faeries there delight in revelry and celebration. But now their glade has fallen silent.\n\nScouts bring reports of the strange masked night fae. I know little other than that they are a threat.\n\nFor the sake of Ardenweald, they must be eliminated. Slay any you encounter.", completion = "Grim work, but necessary. May they be reborn into useful vassals of Ardenweald once more.", objectives = "Slay 15 masked night fae in Shimmerbough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58266] = { id = 58266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break It Down", description = "I've seen the ritual. It's... terrifying.\n\nBut the altars seem to be the key. If only I had my pyrotechnic powder, I could blast them to bits!\n\n<Primrose is silent for a moment, then takes a deep breath.>\n\nIf you could get the powder and guard me, we could blow up those altars.\n\nI stashed as much as I could in our dwellings. They don't seem to care any more.\n\nYou don't have wings, but a pinch of faerie dust should work for a short time.\n\nLet's do this before I change my mind!", completion = "We did it! All the altars are destroyed!", objectives = "Use Primrose's Pyrotechnic Powder to destroy 5 Ritual Altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58267] = { id = 58267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Mask", description = "It's time to end this.\n\nWhen I first hid, I saw a dark shape on the northeast platform. I think that's their leader.\n\nNow that they can't perform any more rituals, we should be able to scare them off.\n\n<Primrose pauses for a moment.>\n\nI... I just wanted to say thank you. I never could have done this without your help. Now, let's drive out this enemy and retake the village!", completion = "I see. This is terrible news.", objectives = "Confront the leader of the possessed fae in Shimmerbough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58268] = { id = 58268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the High Ground", description = "The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath.\n\nHis forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed.\n\nWe will take the ridge from him before that can happen.", completion = "With that ridge clear, we'll be safe to advance.", objectives = "Destroy the three enemy positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58271] = { id = 58271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidflame Ritual" }
quests[58272] = { id = 58272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words Have Power", description = "The Stoneborn Rebels have left behind recruitment pamphlets. Recovering these for the venthyr may earn some much needed favor.", progress = "Uncouth and vile documents, but written in a rather elegant hand. The Prince always had better penmanship than sense.", completion = "Ugh, vile things. Give them to me and I will see them properly disposed of.\n\nHere, for your troubles. Perhaps this reward will help wipe the filth of these documents from your fingertips.", objectives = "Collect 9 Rebellion Pamphlets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58273] = { id = 58273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servant of N'Zoth", description = "{class}...\n\nI have watched you... I have felt your bloodlust. \n\nBut you serve false prophets... the Horde is an illusion... I am a god!\n\nProve to me you are worthy of my gift... kill those who are to betray you...\n\nKill... the Horde!", objectives = "Use the N'lyeth, Sliver of N'zoth to change your faction from Horde to become devoted to N'Zoth. Then slay 10 Horde players without dying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58274] = { id = 58274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servant of N'Zoth", description = "{class}...\n\nI have watched you... I have felt your bloodlust. \n\nBut you serve false prophets... the Alliance is an illusion... I am a god!\n\nProve to me you are worthy of my gift... kill those who are to betray you...\n\nKill... the Alliance!", objectives = "Use the N'lyeth, Sliver of N'zoth to change your faction from Alliance to become devoted to N'Zoth. Then slay 10 Alliance players without dying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58275] = { id = 58275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monstrous Summoning" }
quests[58276] = { id = 58276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mar'at In Flames" }
quests[58277] = { id = 58277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Deceivers", description = "The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir.\n\nThough not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself.\n\nWe must not allow their machinations to go unchecked.", completion = "We cannot let these creatures roam Uldum unhindered.\n\nYou have done well to cull their numbers.", objectives = "Kill 8 K'thir minions in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58279] = { id = 58279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quartermaster's Bounty", progress = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", completion = "Victory at any cost." }
quests[58281] = { id = 58281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Armaments", description = "Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes.\n\nThough the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts.\n\nCan you help?", progress = "Have you returned with the armor?", completion = "Thank the Light you've returned! Our soldiers need this armor badly. \n\nYour efforts will safeguard the lives of many in Ramkahen, {class}.", objectives = "Collect 10 pieces of Amathet Armor from armored Amathet tol'vir in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58282] = { id = 58282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down From the Sky", description = "The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous.\n\nYou have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once.\n\nWill you help?", completion = "The Amathet's arrows no longer darken our skies.\n\nWe must take this opportunity to strike!", objectives = "Kill 8 Amathet Bowmen in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58283] = { id = 58283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Leading the Blind", description = "The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. \n\nThose that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning.\n\nThey must be stopped.", completion = "I take no joy in the deaths of my brethren, but the Amathet must be stopped.\n\nYou have my thanks.", objectives = "Kill 8 Amathet priests in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58284] = { id = 58284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writs of the Sun King", description = "Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners.\n\nI would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. \n\nYou seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.", progress = "Have you found anything interesting?", completion = "The markings on these are fascinating!\n\nI'll have my researchers begin deciphering these right away!", objectives = "Collect 6 Writs of the Sun King from Suntouched Amathet in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58285] = { id = 58285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Artifacts", description = "Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. \n\nI'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found!\n\nOf course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? \n\nCare to help?", progress = "Any luck with the titan artifacts?", completion = "You really do come through, don't you?\n\nYou know, we could use some reliable folks like you in the League...", objectives = "Collect 6 Titan Artifacts in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58286] = { id = 58286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Far From Home", description = "The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. \n\nFortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. \n\nWe must take any opportunity we can to free them and return them to their homes.", completion = "We have seen the return of many of our people, thanks to you.\n\nYou have my gratitude.", objectives = "Free 6 Enslaved Tol'vir in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58287] = { id = 58287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smashing Plan", description = "Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. \n\nI don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical.\n\nJust don't tell the Explorers' League. I'll never hear the end of it.", completion = "Good work, {class}.\n\nSlowly but surely, we chip away at the Amathet's resolve.", objectives = "Destroy 4 Amathet Idols and 2 Suntouched Obelisks in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58288] = { id = 58288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sun King's Chosen", description = "On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with.\n\nSeek out the strongest of their numbers and bring them down in front of their eyes. \n\nWe will show them the strength of Uldum!", completion = "Well struck, {class}!\n\nWe will find a way to break the Amathet yet!", objectives = "Defeat 3 rare Amathet enemies in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58289] = { id = 58289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guarded Secrets", description = "From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them!\n\nOf course, that would be a lot easier if they weren't trying to kill us. \n\nIf you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!", completion = "Fascinating find!\n\nI can't wait until the situation here calms down enough that we can get a look into these old tombs ourselves!", objectives = "Loot 3 Amathet Caches in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58290] = { id = 58290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Amathet", description = "The soldiers of Ramkahen are hearty and reliable. \n\nI would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle.\n\nI don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.", completion = "Good work, {class}. My soldiers should be able to take care of the rest.", objectives = "Kill 6 elite Amathet enemies in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58291] = { id = 58291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Poachers", description = "The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds.\n\nWe need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.", progress = "Have you brought back the pelts?", completion = "You're a life-saver, friend.\n\nHere's your reward, as promised.", objectives = "Collect 6 Rugged Hyena Pelts from Amathet Hunters or by skinning hyenas in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58297] = { id = 58297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of the Daredevil", description = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", progress = "Place the Faceless Mask of the Daredevil on the altar.", completion = "The path of the Daredevil is available to you if you dare.", objectives = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58314] = { id = 58314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of the Burned Bridge", description = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", progress = "Place the Faceless Mask of the Burned Bridge on the altar.", completion = "The treacherous path of the Burned Bridge will be available to you if you wish to tread it.", objectives = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58316] = { id = 58316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of the Dark Imagination", description = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", progress = "Place the Faceless Mask of the Dark Imagination on the altar.", completion = "The risks at the edges of your sanity will now manifest if you so choose to engage them.", objectives = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58317] = { id = 58317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of the Pained", description = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", progress = "Place the Faceless Mask of the Pained on the altar.", completion = "As my madness and torment is not enough, feel free to invite even more pain in the future.", objectives = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58318] = { id = 58318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of the Long Night", description = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", progress = "Place the Faceless Mask of the Long Night on the altar.", completion = "Taking a step towards the Longest Night is already acknowledging the sanity you have lost. Do you risk the rest on such a fools errand?", objectives = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58321] = { id = 58321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncommon Core", description = "Our scouts have reported that the Amathet are constructing new titanic watchers. \n\nWe had long thought this art was lost to the sands of time. It would appear we were mistaken.\n\nI needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum. We must unlock the secrets of their construction!\n\nThe power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.", progress = "Have you obtained the core?", completion = "Marvelous! I have never seen its like!\n\nI will have this sent to my artificers at once! With luck, they can unlock the lost knowledge within.", objectives = "Collect a Titanic Core from an Ivory Watcher in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58325] = { id = 58325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watcher Emil", description = "Watcher Emil is my trusted overseer of the catacombs. Before I was thrown into the Maw, half of the mirror was entrusted to him.\n\nI had him stationed at the Catacombs of Regret. But I do not know where in the sprawl he is.\n\nThere is a guard station near the entrance to the catacombs. Start the search there. There is an officer who can help us, I--I can't remember who. That is, provided they survived this whole mess.\n\nYou must find Emil at once. We may not have much time.", progress = "A friend of the Curator?", completion = "That wasn't the first assassin I've had to deal with so far. And it won't be the last.\n\nThe Curator must have sent you. Someone has turned our allies at Archivam against us... \n\nI have the mirror shard she entrusted to me. We must move quickly, friend.", objectives = "Search for Watcher Emil in the Catacombs of Regret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58326] = { id = 58326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combing the Catacombs", description = "When the anima drought began, our defenses began to fail. \n\nOur guards, weakened by the lack of anima, became overrun as the sinstones this land is built upon rose up around us. Not to mention the manifestations of the souls who can no longer be tended to are running wild.\n\nYou may be able to help us, mortal. Please, we can barely hold this position... and I don't know for how much longer.", completion = "Thank you. Do me a favor and don't tell the Curator? She won't be pleased with the state of things.", objectives = "Kill 12 Manifestations and 3 Sinstone Rampagers in the Catacombs of Regret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58327] = { id = 58327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snacks for Stonehead", description = "<Stonehead has amassed a wide variety of half-eaten oddities.\n\nHe'd certainly appreciate you bringing some new, creative snacks for him to try.>", progress = "Tummy rumbly...", completion = "<Stonehead's eyes light up when he sees the massive pile of semi-edible delicacies you brought him.>\n\nYou best bud! Best bud free to go wherever he want!", objectives = "Collect a sampling of snacks from across the Ember Ward for Stonehead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58328] = { id = 58328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TBD", description = "Bribe Boulderfoot", sourceObjective = "TBD", sourceObjectiveStatus = "unverified-source-field" }
quests[58334] = { id = 58334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall In Flames" }
quests[58337] = { id = 58337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Out", description = "Our reinforcements never came, leaving us unable to tend to the souls here. They have begun to break out of their cells. Many of them are not ready for the next step in the process.\n\nTake these iron chains. They can be used to rein them under your control. \n\nOnce you have a soul bound, you can return them to any intact cage you can find.", completion = "Thank you, {name}. The souls are filled with vanity, rage, and sadness.\n\nSome more confinement will help them confront their past.", objectives = "Use the Chains of Regret on Escaped Captives and bring them to any intact Catacombs Cage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58339] = { id = 58339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward" }
