quests[58348] = { id = 58348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58351] = { id = 58351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hills Have Eyes", description = "The other houses have yet to launch a full scale assault, but do not mistake their cowardice for incompetence.\n\nAny tactician worth their weight in maldracite knows the value of espionage. I suspect that the agents of our foes skulk within our own ranks as we speak.\n\nTake one of my hounds. It will know our enemies by their scent. Once the pests have been discovered, exterminate them.", progress = "Get moving!", completion = "If they cannot properly evade detection, then they do not deserve to survive.", objectives = "Uncover hidden spies with the Chosen Corpsehound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58352] = { id = 58352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
