quests[58370] = { id = 58370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered Demolisher" }
quests[58372] = { id = 58372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lead the Way", description = "We must move now. That won't be the last assassin we face.\n\nI can provide some cover of darkness, but mind that the spell is not infallible.\n\nEnough talking. The Curator needs us and my mirror shard to get to her as soon as possible.", completion = "Thank you for bringing him here safely, {name}. I am glad he is alive.\n\nWith his mirror shard in hand, we now have the unfortunate task of obtaining Mateo's mirror shard.\n\nI cannot believe he betrayed us. Many venthyr have reverted to their sinful ways it seems...", objectives = "Escort Watcher Emil out of the Catacombs of Regret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58373] = { id = 58373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", progress = "Without the items MOTHER cannot guarantee safe passage.", completion = "With these items, MOTHER can guarantee safe access to this area.", objectives = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58374] = { id = 58374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", progress = "Without the items MOTHER cannot guarantee safe passage.", completion = "With these items, MOTHER can guarantee safe access to this area.", objectives = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Heroic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58375] = { id = 58375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", progress = "Without the items MOTHER cannot guarantee safe passage.", completion = "With these items, MOTHER can guarantee safe access to this area.", objectives = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58376] = { id = 58376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Construct Part: Necromantic Oil", description = "<This could be used to construct a powerful abomination. Perhaps Rathan will know how we can use it.>", completion = "This ingredient can help construct a very powerful abomination. You should save it incase we find a use for it.", objectives = "Deliver this part to Rathan in Butchers Block.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58379] = { id = 58379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Construct Part: Indomitable Hide", description = "<This could be used to construct a powerful abomination. Perhaps Rathan will know how we can use it.>", completion = "This ingredient can help construct a very powerful abomination. You should save it incase we find a use for it.", objectives = "Deliver this part to Rathan in Butchers Block.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58382] = { id = 58382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Worth Saving", completion = "It shall not be easy to redeem Kael'thas Sunstrider, and the outcome is far from guaranteed.\n\nBut we must attempt it nonetheless.", objectives = "Release Kael'thas Sunstrider in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58383] = { id = 58383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Many Sins of Kael'thas Sunstrider", description = "Kael'thas Sunstrider was on the verge of destruction when we rescued him from Castle Nathria.\n\nDenathrius had infused Kael'thas with unimaginable amounts of anima, each bit carrying with it the sins of others.\n\nIt made his soul strong, but unstable--confused and pushed to the edge of its own existence.\n\nTrust me when I tell you that Kael'thas Sunstrider has enough sins of his own.\n\nAssist me in identifying which of the many sins heaped on his soul are truly his burden to bear.", completion = "To be clear: We did not absolve Kael'thas Sunstrider of any of these sins.\n\nHe might never be absolved of them. It must ultimately be his choice to change.\n\nBut we did stabilize his soul, which means he will at least have the opportunity to make that choice.", objectives = "Help the Accuser identify the sins of Kael'thas Sunstrider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58384] = { id = 58384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dredgers Left Behind", description = "When Prince Renathal fled Darkwall Tower, he was forced to leave many people and belongings behind.\n\nThe powerful relics and weapons were long ago carted off to the Master's lair. But the Prince's dredgers were forced to stay and serve the Master's traitorous lackeys here instead.\n\nYou will be a welcome sight to them--a sign that the Prince has not forgotten them.\n\nIf they are willing to fight, help them escape and I will ensure they are brought safely to Sinfall.", completion = "I must admit, I did not expect the dredgers to be quite so eager to fight for their own freedom.\n\nThe Prince inspires all of us, I suppose.", objectives = "Help 10 dredgers escape Darkwall Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58385] = { id = 58385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Sacrifice", description = "Kael'thas remains unstable in his current state, bursting at the seams with anima.\n\nHe is also an arrogant, selfish moron.\n\nThankfully, I have a lesson that can address both concerns.\n\nTrue leaders sacrifice of themselves to empower those under their care.\n\nMany stoneborn and gargon, including the Prince's own pet, were left dormant in Darkwall by the Master's forces.\n\nOrder Kael'thas to forfeit portions of the anima trapped inside of him to reanimate those dormant stoneborn to aid us.", completion = "Kael'thas Sunstrider may be ready for the ritual of absolution now.", objectives = "Help Kael'thas reanimate the Prince's pet, Vrednic, and other dormant stoneborn in Darkwall Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58386] = { id = 58386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Use My Strengths", description = "<Kael'thas looks around to make sure the Accuser is out of earshot.>\n\nthe Accuser is so obsessed with my negative traits that she has failed to see my strengths!\n\nEven in death, I am incredibly powerful. the Accuser herself said that Denathrius infused me with anima to make me strong.\n\nLet us use that strength for good while I have it!\n\nThis tower once belonged to the Prince of this realm, correct? Let us find his usurper and gain vengeance!\n\nVengeance is a virtue I have always appreciated.", progress = "Yes?", completion = "I do not expect Kael'thas to agree or even understand the value of mercy immediately.\n\nAbsolution is a long, slow process. This was only the first step.", objectives = "Help Kael'thas confront Usurper Simona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58387] = { id = 58387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Each Must Carry Our Own Sins", description = "The Master chained Kael'thas's sinstone to his soul via a dark, corruptive process that left Kael'thas scarred and overburdened.\n\nHe bears the weight of not only his own sins, but the sins of countless other souls on his back. That would be a crushing burden for even the most noble of souls--which Kael'thas is not.\n\nLet us hope your time with Kael'thas has prepared his soul for my ritual.\n\nI must break that cursed burden by removing the foreign sins from his soul, or else we'll lose him forever.", progress = "This must work.", completion = "I cannot comfortably call this a success, but it is likely the best outcome we could have hoped for. Carrying one's sins is no small feat, yet it can be liberating.\n\nTake this chain, if you wish, to display your commitment to owning your own sins. Kael'thas needs it no longer.", objectives = "Complete the ritual of extraction on Kael'thas Sunstrider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58388] = { id = 58388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackbale Betrayers", description = "When the Prince made his final stand at Darkwall Tower, he called for aid from the many noble houses here in the Chalice District.\n\nNone came.\n\nMost simply avoided the conflict, out of self-preservation. A shameful, but understandable choice.\n\nHowever, one house took action. Lord Blackbale replied with cruel mockery and sent his stoneborn to aid the Master's armies instead.\n\nPrince Renathal has not forgotten that betrayal.\n\nKael'thas seeks vengeance? Let him have some. Start with the stoneborn.", completion = "Did any of the Blackbale venthyr show signs of regret?\n\nWe had hoped to recruit some to our cause eventually.", objectives = "Kill 4 Blackbale Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58389] = { id = 58389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxian Weapons", description = "<The weapon you find seems unlike those wielded by most venthyr, yet the marks it bears are unmistakably familiar...\n\nIt would be wise to seek out more such weapons and bring them to the Accuser.>", progress = "What are you carrying? Those do not belong here...", completion = "The Blackbale venthyr are wielding the weapons of the Maldraxxi army?\n\nThat would mean...", objectives = "Collect 8 Maldraxxian Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58391] = { id = 58391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconnaissance... for my, uh, Recovery", completion = "A lich? So close?\n\nCan you feel its presence? I once could...", objectives = "Spy on the Tithelord's meeting with his Maldraxxian contact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58392] = { id = 58392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's End Destruction", progress = "I hope they put up a fight.", completion = "Traitors and cowards. I have time for neither!", objectives = "Destroy the Maldraxxian camp in Death's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58393] = { id = 58393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Executions", description = "I confess that I do not comprehend the full array of potential consequences wrought by the Tithelord's anima-sharing arrangement.\n\nBut I am very aware of the dangers posed by a lich with access to power.\n\nI am also very aware that resolving this situation is important to the Accuser, which, given my current situation, makes it important to me.\n\nWe should eliminate the muscle behind the anima transfer logistics. Without that, the shipments will halt.", progress = "They really do grow their monsters big here, do they not?", completion = "The bigger they are... the bigger the explosion at the end. Ha!", objectives = "Kill the dredger giants in Death's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58394] = { id = 58394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Ouix'Ara", description = "Can you feel it? The chill in your bones... the energy... power...\n\nShe's here. The lich.\n\nTake me to her. I must speak with her, in my own way.", progress = "No good has ever come from a lich, {name}.", completion = "It was unlikely that she'd tell us anything useful, but I had to try.", objectives = "Kill Lady Ouix'Ara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58395] = { id = 58395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Vengeance For One Day", description = "After the Sunwell's destruction and the near extermination of my people, I vowed to claim vengeance upon Arthas and Kel'Thuzad. But I needed power to see that happen, and to seize that power I...\n\n<Kael'thas grows quiet.>\n\nI... am ready to return to Sinfall. I must recover my strength for what lies ahead.\n\nAs the Accuser is so fond of reminding me, I have... much to ponder.\n\nLet us inform our allies of the enemy we have revealed.", completion = "Maldraxxus is sworn to defend Revendreth from outside invaders, not siphon off our anima.\n\nAccept this gift for your role in bringing this conspiracy to light, {name}.\n\nWe will need time to calculate our next move, but I am certain that you will be a key part of it.", objectives = "Deliver Kael'thas to Sinfall and report to Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58406] = { id = 58406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror to Maldraxxus", description = "I've received word that Laurent's made substantial progress with his repairs. \n\nOnce the mirror has been restored, we can realize our efforts to recover the final medallion. \n\nHead to the ramparts and see if his work is near completion.", completion = "This mirror is my greatest achievement. It links directly to the necropolis that floats above the bone fields of Maldraxxus.", objectives = "Find Laurent on the Sinfall ramparts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58407] = { id = 58407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Medallion of Dominion", description = "Laurent speaks the truth. We must not delay. \n\nThis mirror is our entryway into the heart of Maldraxxus. \n\nTogether with Kael'thas, we will find Kel'Thuzad and rip the Medallion of Dominion from his undeserving grasp.", completion = "Revendreth can now begin the return to its true purpose. May we walk into brighter futures together.\n\n<Prince Renathal smiles.>\n\nI could not help but notice that Vrednic, my loyal gargon, has taken an affinity to you, as I have.\n\nIf you would have him, I am certain he would enjoy accompanying you. Together, you shall instill fear into our enemies as he bears you into our next battle.", objectives = "Use Laurent's mirror to enter Maldraxxus and recover the Medallion of Dominion from Kel'Thuzad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58420] = { id = 58420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foul Annoyance", description = "The Hozen are opportunistic and weak. It does not surprise me that some of their kind have thrown their lot in with the Old Gods.\n\nWe should take care of them before they become more than a nuisance.", completion = "Good. The Vale is better off without their filth.", objectives = "Kill 7 Squidtail hozen in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58421] = { id = 58421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Access", description = "Mateo will have the other mirror shard we need to access the medallion. He is likely in my former manor in Archivam.\n\nIt is guarded by Nourman, a loyal dredger. Nourman is ever committed to his duties, regardless of the situation.\n\nMateo likely maintained the same rule to access the manor--possess the fangs of those granted access. If you collect the fangs of the commanders of his operation, Nourman will let you pass.", progress = "Oi, you want to access the manor? Let me see your fangs.", completion = "<Nourman carefully inspects the fangs.>\n\nChecks out. Strange that you got so many. \n\nSay, you don't look like a venthyr. \n\n<Nourman shrugs.>\n\nDon't matter to me. You got the fangs, you go inside. Them's the rules.", objectives = "Collect the fangs of Examiner Daciana, Examiner Boian, and Examiner Ionata.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58422] = { id = 58422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of the Conquerors", description = "The invading minions of N'Zoth lay claim to lands they are not entitled to. \n\nThe Vale will not be conquered while even one of the Rajani still draws breath.\n\nBurn down their banners as a reminder of this.", progress = "Have you sent our message?", completion = "Good.\n\nThese invaders should know that we are not so easily conquered.", objectives = "Burn 6 Banners of the Black Empire in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58423] = { id = 58423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strongest Among Them", description = "You have shown great strength in your conquests, but new enemies assail the Vale with each day.\n\nSeek out the strongest that our foes have sent forth, and bring them down for their allies to see.", progress = "Tell me of your victories.", completion = "Even minions of the Old Gods must take pause when their champions are laid out before them.\n\nRemember this as the battle rages on.", objectives = "Defeat 3 rare minions of N'Zoth in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58424] = { id = 58424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Eye for an Amulet", description = "Archivam has been overrun by Denathrius's lackeys. \n\nWe must eliminate these intruders. From the look of things, they have resorted to tearing Archivam down to the core for any evidence of the Curator's medallion.\n\nGo, {name}. Stop them before it is too late.", progress = "Are they dead?", completion = "Yes! The rest of those rats will think twice about working with Denathrius.", objectives = "Kill 12 Archivam Intruders and 5 Excavation Enforcers in Archivam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58426] = { id = 58426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Shadow of our Failures", description = "I will personally tend to the absolution of Kael'thas Sunstrider. His current state and trauma requires nothing short of perfect intervention and instruction to correct.\n\nI would welcome your assistance in this. I sense a bond between Kael'thas and yourself. I think your presence may help inspire him down a better path.\n\nIf you're willing, meet us at Darkwall Tower.\n\nPrince Renathal suffered a great defeat there once. Perhaps a better fate will be found this time.", completion = "I'm pleased you came. Let's begin.", objectives = "Meet the Accuser and Kael'thas at Darkwall Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58428] = { id = 58428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crypt Crashers", description = "There's one more thing I forgot to mention. Apologies, {name}.\n\nThe mirror, once complete, is inherently cursed by design. \n\nYou need to locate my Death Lotus Powder. It was in one of the crypts in Archivam... I cannot recall which one. \n\nI'm afraid you may have to brute force this one, {name}.", progress = "Do you have the powder?", completion = "Excellent. Now we can enter the mirror safely.", objectives = "Collect Stonebreaker Mallets to destroy crypt doors in search of Death Lotus Powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58431] = { id = 58431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool of Potions", description = "I shall teach you about the Pool of Potions. The potions we create here have a variety of beneficial effects.\n\nKill the slimes in the surrounding ruins and collect the Oozing Ingredient: Viscous Oil they may drop. Each slime can produce a great quantity of oil, so you'll only be able to carry one slime's worth at a time. \n\nDeliver this oil to the Pool of Potions and toss it in.", progress = "Have you brought enough oil?", completion = "We shall all share in this fabulous brew you have created!", objectives = "Deliver three Oozing Ingredient: Viscous Oil to the Pool of Potions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58432] = { id = 58432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Old, Something Used", description = "Want new luckydos? Chordy is best at finding luckydos!\n\nWant to go look around with Chordy?\n\n<Chordy looks at you pleadingly with his large eye.>", progress = "Did we find anything good?", completion = "These are valuable resources. Thank you, Maw Walker.", objectives = "Use Chordy to locate and collect 10 valuable salvage in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58433] = { id = 58433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Attrition", description = "This is not some simple raid or protest. These stoneborn mean to steal the anima this convoy was carrying.\n\nThat anima was destined to be tithed to the Master. There is a drought on and we cannot let these vagabonds and miscreants steal our hard-earned anima.\n\nRecover the tithe if you can and I will see to your notoriety.", progress = "What have you found?", completion = "Well done, mortal. Stoneborn require anima to exist. Without it, they return to their stone form. This supply hurt them more than destroying thirty of their rebels.", objectives = "Recover the Anima Canister.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58435] = { id = 58435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Vulpera", description = "The Horde has come to truly value the Vulpera, thanks to your efforts. \n\nYou are the most... vulperan vulpera that I know!\n\nVisit me in the Vulpera Hideaway in Vol'dun. Kiro had me put together a small memento in appreciation of your efforts.", completion = "Your sense of adventure, you skill, your drive to explore... you just make us so proud. The Horde is better for having us!\n\nWith that in mind, {name}, take this gift. You carry us with you, wherever you go.", objectives = "Meet Hagashi at the Vulpera Hideaway in Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58436] = { id = 58436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Mechagnome", description = "{name}, we could not be more pleased with your progress. You represent us well with the Alliance.\n\nReturn to Mechagon City at your earliest convenience. Waren has created a gift for you.", completion = "Continue in this manner, and our people will continue to advance at a rapid pace. \n\nThere is so much left to discover! Continue to learn and grow, {name}!", objectives = "Meet Prince Erazmin in Mechagon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58437] = { id = 58437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts to a Whole", description = "Damien has some great dreams, but without more abominations, this training facility will not succeed! \n\nI have a plan though!  If we can't recruit more abominations, then we shall make them ourselves!\n\nI need you to make some corpses, then mark them for harvesting with a flag. I will do the rest.", objectives = "Mark 15 corpses for harvesting", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58438] = { id = 58438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58439] = { id = 58439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58440] = { id = 58440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror, Mirror...", description = "We have what we need to get you through, {name}.\n\nMy medallion lies on the other side of the mirror. Once through, my medallion will be there... somewhere. \n\nPlease be careful. My mind may be weakened, but I do remember working with the Accuser to protect the crypt's interior.\n\nI should be able to tell you everything about this place, but I am afraid that just is not the case anymore.", progress = "My medallion? Do you have it?", completion = "You found the medallion! I wish you had found it under better circumstances. I do miss celebrating.\n\nBut I should reward you. Yes, a reward! You must take these. May they serve you well!", objectives = "Enter the Curator's mirror. Then, collect the Medallion of Avarice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58442] = { id = 58442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consuming Maw" }
quests[58443] = { id = 58443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Care of Kael'thas", description = "Kael'thas is free from the twisted corruption of the Master, but he is not truly \"free\" yet.\n\nHe carries more than enough burdens from his own sins to condemn him to the Maw.\n\nWe must be vigilant in encouraging and forcing him to atone for his mistakes. If he cannot right the many wrongs of his mortal life, he will be doomed forever.\n\nYou are having a positive effect on him. Please, accompany us down to the Chalice District for his next lesson.", completion = "We're ready to begin our next lesson.", objectives = "Meet the Accuser and Kael'thas in the Chalice District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58444] = { id = 58444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sinfall", description = "{name}, we must get the medallion back to Sinfall as soon as possible. \n\nWe saw how fierce Mateo's forces were, just imagine what destruction Denathrius will bring if we linger around.\n\nI will return to Absolution Crypt in a moment. With all the work you've done, I can begin to resume my duties.\n\nMy first order of business will be to recruit a new sinkeeper. Oh how I dread interviews...", progress = "Did you retrieve the Medallion of Avarice?", completion = "Excellent work, {name}.\n\nWith the Curator's medallion in hand, we are one step closer to victory.", objectives = "Bring the medallion to Prince Renathal at Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58445] = { id = 58445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Night", description = "It is fortunate you are here, {name}.\n\nThiernax believes he may know how to save Tyrande from the fate he himself suffered as the Night Warrior.\n\nLet us hear what he has to say.", progress = "It cannot be easy for Thiernax to share his memories of becoming the Night Warrior... or the pain that followed.", completion = "Thiernax suggests a bold plan. Locating the other former Night Warriors will not prove easy.", objectives = "Listen to Thiernax's plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58446] = { id = 58446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracker Tracking", description = "We will require the aid of an expert tracker if we are to find the other Night Warriors.\n\nThe Wild Hunt possesses legendary skills in such matters. No quarry can elude them.\n\nSpeak with Lord Herne. With one of his hunters at your side, your search will surely be successful.", completion = "Ah, yes. I know of whom you speak.", objectives = "Speak with Lord Herne and locate the Wild Hunt tracker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58447] = { id = 58447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monster Hunting", description = "Make ready, {class}. We hunt a worldeater.\n\nThey are the largest of devourers, massive beings who can drain anima from an entire region within a matter of moments. \n\nWith Ardenweald suffering from the drought, a worldeater's presence could prove disastrous.\n\nStill, we must not rush into battle without first understanding our prey. Tread the Elder Stand with me. Even creatures such as these leave spoor.\n\nKnowing our quarry will be what allows us to slay it.", completion = "This problem just got a lot larger. We need a new plan.", objectives = "Search for clues and tracks to learn more about the worldeater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58449] = { id = 58449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acid Reflux", description = "We will need to be properly prepared before we can face Voras.\n\nThe digestive juices of Ardenweald's gorm dissipate the anima in their food. Ingesting them causes devourers no small discomfort.\n\nFor a beast of that size, we will need a lot of it to have any effect. There should be plenty of gorm in the hive to the east.\n\nLong ago, an artisan gave me a tool that he said would be useful against the gorm, should I ever need it. You may borrow it.", progress = "We will need those digestive sacs if we are to disrupt the worldeater enough to slay it, {name}.", completion = "<Reldorn hefts the sacs, which bulge uncomfortably.>\n\nSo many? Just how big is this thing you two are hunting, anyway?", objectives = "Use the Gormherd Branch on gorm in Gormhive to retrieve 50 Bulging Digestive Sacs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58450] = { id = 58450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Instincts", description = "Voras is clearly content to roam the Elder Stand. We will need a way to lure it to us once we are ready to fight.\n\nDid you notice the wildseeds in the clearing where we spotted it? Voras must be feasting on the concentrated anima contained within them.\n\nThere should still be some expended wildseeds from before the drought in the Gormhive. Let us create bait too tempting for Voras to ignore.", progress = "It may take several wildseeds, but with enough concentrated anima, we should be able to lure out Voras.", completion = "I am amazed that this contains so much concentrated anima. You will surely lure a devourer to you with this!", objectives = "Collect 8 Life-Hardened Anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58451] = { id = 58451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voras, The Realm Eater", description = "We have everything we need, {name}. Now only the kill remains.\n\nWe set the lure, weaken the beast, and land the final blow.\n\nHunting is a battle of wills. Life or death hangs in the balance for all of us. It has always been this way, on Azeroth as in Ardenweald.\n\nLet the hunt begin.", progress = "Voras cannot continue to leech anima from Ardenweald. We must stop it now.", completion = "The hunt is over. We have prevailed.", objectives = "Slay Voras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58452] = { id = 58452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Shadows", description = "The quarry has been slain, and my duties fulfilled. The tirnenn are more than capable of defending their home from the lesser devourers. Nature will take its course.\n\nI will report back to Lord Herne and meet you at the Heart of the Forest. There we shall see what I will be hunting next.", completion = "Even in the afterlife, the legend of Huln Highmountain continues to grow.\n\nYou have done well to secure his aid, {name}. Now let our search begin.", objectives = "Speak with Ysera in the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58454] = { id = 58454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spoiling For A Fight", description = "Your contribution of anima has aided our operation here greatly. Several of our more famous competitors have come here lured by the flow of new anima.\n\nWould you like to test yourself versus the famous Sabriel? There could be much profit for everyone, if you were to defeat her.\n\nI can add her to the schedule, she will appear soon if you defeat the other challengers.", objectives = "Defeat Sabriel the Bonecleaver in the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58455] = { id = 58455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowy Showdown", description = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", completion = "These Shadowy Figures have been an annoyance for too long now. Get in there, and stop them.", objectives = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58456] = { id = 58456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowy Showdown", description = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", completion = "These Shadowy Figures have been an annoyance for too long now. Get in there, and stop them.", objectives = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58457] = { id = 58457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows of Blackrock", description = "We've finally tracked those pesky Shadowy Figures down, they should all be in there. They seem highly skilled, you're going to need to bring your best teams in there if you have any chance of winning.\n\nLet me know when you are ready.", progress = "I can teleport you in, but after that, you're on your own.", completion = "Amazing, you stopped them! Who knows what crazy things they would have done had we not intervened, and at just the right moment. Well done!", objectives = "Stop the Shadowy Figures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58458] = { id = 58458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Challenge: Blackrock Depths", description = "Those Shadowy Figures are up to no good again, are you sure you want to face them? If you really want to go back in there, I'm not going to stop you.", progress = "I can teleport you back in there, but you're on your own once you're inside. Good luck.", completion = "Amazing, you stopped them! Who knows what crazy things they would have done had we not intervened, and at just the right moment. Well done!", objectives = "Stop the Shadowy Figures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58460] = { id = 58460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshals of Madness", description = "The n'raqi have long served as the commanders and taskmasters of the Old Gods' forces. Their presence on the field of battle shows that this invasion is a coordinated effort rather than a random outbreak of corruption.\n\nLed by these faceless masters, the chaotic forces of the Old Gods transform into capable military.\n\nWe must make it a priority to fell these creatures. Only then might we take the upper hand against N'Zoth.", completion = "The loss of their leaders should prove to scatter N'Zoth's forces in the Vale.\n\nThis should provide us with the advantage we need to crush them once and for all.", objectives = "Kill 6 faceless minions of N'Zoth in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58461] = { id = 58461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomes of Ancient Madness", description = "In times like these, it becomes necessary for all of the denizens of the Vale to pitch in and do their part. Unfortunately, I have never been much of a fighter, so my usefulness in times of war is limited.\n\nHowever, I may be able to do some good. You see, we know very little about the invaders we face, and knowledge can be a very powerful weapon.\n\nI think I have seen tomes carried by some of the k'thir. If you could bring some to me, I may be able to glean something useful from their writings.", progress = "Have you managed to procure the tomes?", completion = "Yes, this is exactly what I was looking for! I'll start researching these at once!\n\nAh, it's good to feel useful!", objectives = "Collect 8 Tomes of Ancient Madness from k'thir enemies in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58462] = { id = 58462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windows to the Soul", description = "Were it not enough for our enemy to apply deadly force against us, their minions also strike into the very heart of our defenders.\n\nI speak, of course, of the eyes. They peer into the souls of our warriors and produce their darkest fears against them.\n\nIf we have any hope to defeat this foe, they must be destroyed.", progress = "Is your task complete?", completion = "The foul eyes are no more, and our warriors' courage is restored.\n\nThank you, {name}.", objectives = "Kill 6 Eyes of the Empire in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58463] = { id = 58463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawns of Madness", description = "To see the Vale of Eternal Blossoms recover from the Sha to its former beauty, only to see it tainted by the Old Gods once more, it makes the blood boil!\n\nWe must root out the Old God's corruption before it can take hold of this land again. I have seen the fleshbeasts that accompany N'Zoth's forces spreading his corruption where they tread.\n\nMake sure they tread no longer.", progress = "I will not see the Vale fall again!", completion = "You have done well.\n\nWe must not let N'Zoth take hold of this land!", objectives = "Kill 10 fleshbeasts in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58464] = { id = 58464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deephive Decimation", description = "A sect of the mantid swarm calling themselves the \"Deephive\" have taken hold of the Big Blossom mine. These mantid have fully given themselves up to the Old Gods' corruption, making them especially dangerous.\n\nWe cannot allow the Deephive to run amok in the Vale. Do what must be done.", completion = "The mantid are incessant, but we will drive them back.\n\nAt least you've taken care of the worst of their numbers.", objectives = "Kill 10 Deephive mantid within the Big Blossom Mine in Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58465] = { id = 58465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption Manifest", description = "The corruption of the Old Gods is often so foul it manifests itself in physical form. \n\nWe have seen this with the Sha. This time is no different.\n\nCull this corruption wherever you see it spread. It must not be left to flourish.", completion = "I can see the stains of N'Zoth's corruption on your weapons.\n\nWell struck, {class}.", objectives = "Kill 8 Putrid Ichors in Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58466] = { id = 58466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torment From Beyond", description = "As if it were not bad enough that N'Zoth seeks to dominate those living in the Vale, my scouts report they now seek to dominate the dead!\n\nThe Shado-Pan have their hands full defending the living. Can we rely on you to put an end to this disgrace?", progress = "N'Zoth must be stopped.", completion = "I had my misgivings about your people at first, but it seems you truly have Pandaria's well-being at heart.\n\nThank you, {class}.", objectives = "Release 6 Ancient Pandaren Spirits in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58467] = { id = 58467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of Mind and Body", description = "N'Zoth's forces struck the Vale suddenly. By the time I and my Shado-Pan arrived, many of the Golden Lotus had already been taken captive by the Old God's forces.\n\nEven with our combined might, we have only been able to hold off the invaders from taking more of our people. Those already taken, however, are still within the clutches of the Old God.\n\nI know we have had our differences, {name}, but if you could aid us in their recovery, the Shado-Pan would be in your debt.", progress = "Any news of the captives?", completion = "I do not wish to dwell upon the fate that would have otherwise befell those you rescued.\n\nYou are a true champion of pandaria, {class}.", objectives = "Rescue 6 captive pandaren in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58468] = { id = 58468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Darkness", description = "Shado-Pan scouts have spotted evidence of a new mantid hatchery within the Big Blossom mine. It seems these Deephive mantid are looking to create new corrupted spawn to serve N'Zoth.\n\nIf these eggs were allowed to hatch, a new swarm empowered by the Old God could blacken the skies of the Vale and plunge Pandaria into darkness.\n\nWe will not allow that to happen, will we?", completion = "The swarm has been abated, for now.\n\nKeep an eye out for any new hatcheries. We cannot afford to leave the Deephive unchecked.", objectives = "Destroy 6 Corrupted Incubators in the Big Blossom Mine in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58469] = { id = 58469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears in the Vale", description = "As N'Zoth's influence spreads within the Vale, our very reality begins to break down. \n\nThe Old God's power has created tears in the fabric our world, acting as doorways for his minions to invade from his dark realm.\n\nAs long as these tears exist, we will never be free from N'Zoth's grasp. Close them, and stem the tide of his corruption!", progress = "Our reality weakens with each passing day.", completion = "The paths are closed, and the Vale is more itself again.\n\nThank you, {name}.", objectives = "Close 3 Void Tears within the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58470] = { id = 58470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Curiosities", description = "I understand that the Black Empire poses a grave threat to Pandaria, but we may also use this as an opportunity!\n\nThough we've faced them several times before, very little is known about the Old Gods or N'Zoth's mysterious realm of Ny'alotha. \n\nWhen studying ancient civilizations, we often rely on artifacts to unlock the deepest mysteries lost to time. I wonder if some such artifacts could be found among the Old God's forces?\n\nIt can't hurt to check, right?", progress = "Did you find anything interesting?", completion = "Spendid! Just think of what ancient mysteries we could learn from these artifacts!\n\nI hope you didn't go through too much trouble to get these.", objectives = "Collect 3 Artifacts of the Black Empire from Black Empire Caches in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58471] = { id = 58471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Notation", description = "Even given the Sha's origins with the Old Gods, we in Pandaria still know very little of them.\n\nI would like to take this opportunity to add whatever information I can about them to the archives of the Lorewalkers. Of course, that becomes a bit problematic when they're trying to kill us.\n\nThat doesn't seem to be a problem for you, though. Could you do me a favor and jot down some notes about what you encounter out there?  It could help a great deal towards understanding what we're fighting.", completion = "Fantastic! This is very thorough!\n\nI must ask, though, how do you maintain such impeccable penmanship in the heat of battle?", objectives = "Use the Lorewalker's Notebook to gather notes about the faceless, k'thir, and fleshbeasts in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58472] = { id = 58472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Farewell to Arms", description = "The Maldraxxi toil away just behind us. I care not if you consider them allies or traitors, so long as you remove them from Revendreth.\n\nDestroy their encampment. Purge it from our soil, and ensure such an affront never occurs again.\n\nThe means are not important. All that matters is that these heretics remember the consequences of trifling with true power.", progress = "Well?", completion = "Let this prove our sense of honor.", objectives = "Destroy the Maldraxxi encampment at Death's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58473] = { id = 58473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tirna Noch", description = "It is clear that we need more anima than this grove can provide. I may know of a way we can acquire some.\n\nMany of the masked fae have been collecting anima for some unknown purpose. I propose we take it back from them.\n\nThe Wild Hunt has tracked them to Tirna Noch... my former grove.\n\nLong has it been since I walked beneath its boughs. Not since it was left to wither so that other groves might survive.\n\nI remember it well...", completion = "I never thought I would return to Tirna Noch. The place of so many memories. So many regrets...\n\nBut now is not the time for sentimentality. Now is the time for action.", objectives = "Meet Ara'lon in Tirna Noch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58476] = { id = 58476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing the Thunder", description = "All of the mogu clans are formidable, to be sure, but it is the Zan-Tien that pose the most direct threat to the Golden Lotus. \n\nEven now, their numbers are amassing outside the Golden Pagoda. Many of our warriors are fresh-faced and inexperienced. They would not withstand a mogu assault for long.\n\nAn experienced {class} like you could serve to slow them down significantly. \n\nCare to help?", progress = "What's the word from the front?", completion = "You've probably saved the lives of many Golden Lotus warriors today.", objectives = "Kill 12 Zan-Tien mogu in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58477] = { id = 58477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Blood and Dirt and Bone", description = "The Dokani see themselves fit to wield the ancient magic of anima, but their golems and manifestations are but a fraction of anima's true power.\n\nLiberate them of their prized substance, so that the Rajani may put it to better use.", progress = "What do you bring?", completion = "This will do.\n\nGo now. I am sure you are needed elsewhere.", objectives = "Collect 100 Anima Globule from Dokani mogu and their allies in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58478] = { id = 58478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Stone Unbroken", description = "When the warring clans came into the Vale, the Baruk deigned themselves worthy to lay claim to the ancient grounds of Guo-Lai.\n\nThey are not.\n\nShow these usurpers their place, and you may earn a modicum of favor with the Rajani.", completion = "The Baruk will soon learn their place under the foot of the Rajani.\n\nWell done.", objectives = "Kill 10 Baruk mogu in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58479] = { id = 58479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Crashes", description = "The Zan-Tien like to claim mastery over the power of storms, yet they resort to machines to harness lightning from the sky.\n\nShow these pretenders that the true power of storm and thunder comes from within. Break their toys, and see how they fare without.", completion = "Hah! Let's see how these so-called \"masters of storm\" fare without their precious contraptions!\n\nThis should be entertaining.", objectives = "Destroy 6 Lightning Rods in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58480] = { id = 58480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Read the Roots", description = "When my grove withered, I answered the Queen's call and joined the Wild Hunt.\n\nNothing can be done for Tirna Noch. But it wounds me to see it crawling with foes of the forest.\n\nWe need a great deal of anima. The masked fae must be keeping a stockpile somewhere within the grove--we just need to find it.\n\nThey likely used soulwebs to collect and move the anima. If I examine them, I should be able to pick up the trail.", progress = "I sometimes mourn what was lost. And then I remember what work there is still left to do.", completion = "The Drust have stolen more anima than I expected. To think that they have deprived us of this much in the midst of a drought...\n\nWe must take back whatever we can. Not only for the sake of the wildseed, but to also thwart whatever the Drust intend to do.", objectives = "Investigate the Depleted Soulwebs in Tirna Noch, to find the greatest concentration of anima in the grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58481] = { id = 58481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituals of Blood", description = "Anji and I have fought in many battles, so we know how to handle a few mogu, but the blood magic used by these Dokani is just unsettling!\n\nAs if it weren't bad enough for them to kill everyone in their path, but to use their corpses to fuel their unholy rituals? I just can't stomach it!\n\nDo me a favor. If you ever come across any of these rituals, put a stop to them! Even our enemies don't deserve to be defiled with their dark magic.", progress = "I hope you were able to do something about those rituals.", completion = "It is a relief to know that you've put an end to those rituals.\n\nJust thinking about them turns my stomach.", objectives = "Destroy 6 Blood Fonts in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58483] = { id = 58483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mementos", description = "At Heartwood Grove, I heard tales about the fall of Tirna Noch. I never thought that I would see it with my own eyes.\n\nIt brings me great sadness. And I wonder... if this is the fate that awaits my old grove as well.\n\nI can't believe that everything that was once here is truly gone. \n\nPerhaps there are still some mementos that can be recovered. Something to remember the fallen.", progress = "Is this what lies in store for Heartwood Grove? For my old home?", completion = "Thank you.\n\nI know these are just objects, but they mean so much. Sometimes just holding a piece of one's past can be a comfort.\n\nIt means not everything is lost.", objectives = "Collect Stolen Mementos from slain enemies in Tirna Noch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58484] = { id = 58484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take What You Can", description = "We know that these invaders have taken over the remains of the grove. \n\nBut why? Why are they gathering anima and bringing it all to one place?\n\nAnd how did they enter Ardenweald?\n\nWe should stay alert and take as much anima as we can find. Perhaps some good can come out of all this loss.", progress = "I sometimes mourn what was lost. And then I remember what work there is still left to do.", completion = "This anima will help Dreamweaver complete his ritual... and perhaps save spirits who otherwise would have been lost.\n\nGood work.", objectives = "Take Plundered Anima from stores in Tirna Noch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58485] = { id = 58485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Built to Fall", description = "The Baruk use the forbidden arts of necromancy to trap souls of fallen mogu into the statues that fight for them. \n\nThese tactics are a disgrace to our people, and cannot be allowed to continue.\n\nBreak their precious statues, and give them no vessels with which to contaminate with their stolen spirits.", completion = "As their statues crumble, so too shall their clan.\n\nYou have performed adequately.", objectives = "Destroy 6 Mogu Statues in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58486] = { id = 58486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Drust in the Way", description = "Only the heart of a grove can hold the sheer massive quantity of anima I'm sensing. \n\nWhen my grove was sacrificed, the anima within its heart was reclaimed. Now it brims with anima once again.\n\nAnima that was stolen from other groves.\n\nWe must secure the heart not just for our own sake, but for the entire forest.\n\nI suspect that we will not be allowed to simply trot our way in there. Be prepared for anything.", completion = "We made it to the heart. Well done.\n\nIf that is what all the Drust are truly like, then Ardenweald is in a dire situation, indeed.", objectives = "Slay Vroth, Bulwark of Thros, and make your way to the Heart of the Fallen Tree.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58487] = { id = 58487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder the Plunderers", description = "Our raids on Lei Shen's treasuries did much to ensure the Thunder King's downfall. I think we should employ the same strategy here.\n\nSeek out the hoarded plunder of the mogu clans and relieve them of it. \n\nWe must do all we can to disrupt their advance.", completion = "Well done. We should continue to keep these supplies out of our enemies hands.\n\nEven the smallest measures taken to disrupt our enemy can turn the tide of battle.", objectives = "Loot 3 Mogu Plunder from the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58488] = { id = 58488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go for the Heart", description = "I was right! A great deal of anima has been stored inside the heart of the grove.\n\nThe Drust must have collected it from all over Ardenweald.\n\nAnd now, we will take it back.\n\nQuickly, destroy that barrier and grab the heart. Niya and I will protect you.", progress = "We will reclaim this anima. The Drust will not use it for their own ends.", completion = "Now that we have the heart, we need to find a way out of this place.\n\nAnd I hear the distinct sound of approaching enemies...", objectives = "Destroy the barrier and collect the Heart of Tirna Noch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58490] = { id = 58490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadly Reminder", description = "Our defense is tenuous at best, but the enemy is still hesitant to attack.\n\nAs long as they fear us, they won't be probing our defenses. \n\nYou must keep the pressure on the enemy.  Attack their positions all along our line.", objectives = "Eliminate Enemy forces and positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58496] = { id = 58496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Advisor", description = "<The envelope contains a message from King Anduin Wrynn.>\n\n{name},\n\nEven with the forces of the Horde and Alliance working together, we still have found no trace of N'Zoth's forces. Ever since his release, the Old God has evaded us at every turn.\n\nThe Light only knows what ill he has in store for Azeroth.\n\nMeet me in Stormwind Keep. We must put a plan together to uncover N'Zoth's schemes before it is too late!\n\nLight grant you haste,\nKing Anduin Wrynn", progress = "What is it?", completion = "It would appear that N'Zoth's corruption is already reaching its way into our minds. We have no time to waste.\n\nGo with Magni and Wrathion and see what you can uncover. I will ensure that our forces are ready to defend against any attack.\n\nGood luck.", objectives = "Speak with King Anduin Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58498] = { id = 58498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Warrior King", description = "Ye've done a great deal fer Azeroth, hero, but unfortunately I'm gonna have tae ask ye tae do more. N'Zoth is on the loose, an there's no tellin' when or where he'll strike.\n\nThis battle is one ye can't face alone. When the time comes, ye'll have my hammer at yer side!\n\nBut first, we'll need tae fetch it.", progress = "Need something, champion?", completion = "It'll be good tae be back in the action again. \n\nLet's get goin!", objectives = "Walk with Magni and retrieve Fearbreaker in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58502] = { id = 58502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Heart Is", description = "It's time we put Wrathion's plans in tae motion. \n\nHe'll be headin' back tae the Chamber of Heart, so we should meet him there.", completion = "All right, the gang's all here. \n\nLet's get started!", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58504] = { id = 58504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accusatory Missive", description = "We have received word from Revendreth. It seems that Maldraxxi conspirators have been found skulking within their realm.\n\nAn emissary from Sinfall wishes to discuss the anima reserves we discovered. \n\nJoin me. We depart immediately.", completion = "The pleasure is mine.", objectives = "Meet with the Accuser in the Halls of Atonement in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58505] = { id = 58505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planned Demise", description = "Our defense is tenuous at best, but the enemy is still hesitant to attack.\n\nAs long as they fear us, they won't be probing our defenses. \n\nYou must keep the pressure on the enemy.  Attack their positions all along our line.", objectives = "Eliminate Enemy forces and positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58506] = { id = 58506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Network Diagnostics", description = "Unfortunately, we've got no clue where N'Zoth has been lurking since his escape. We do, however have an idea where he might strike.\n\nBack when the keepers were imprisoning the Old Gods, they built defense mechanisms against their corruption into the titan forges. If N'Zoth wants tae corrupt Azeroth, he'll have tae go through them first.\n\nFortunately, we've got ourselves hooked up tae them now, so we can monitor them from here. Go ahead an' take a look.", progress = "The consoles should tell ye how the forges are holdin' up.", completion = "I was hopin' we'd have more time tae prepare.\n\nLooks like now's the time tae act.", objectives = "Activate the Titan Consoles in the Chamber of Heart to check the status of the titan forges throughout Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58515] = { id = 58515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrounging for Scrolls", description = "The kyrian are known for their collection of scrolls and writings. I'm particularly interested in their texts regarding those who have joined their ranks.\n\nWhy is it that some of the greatest fighters are sent to Bastion and not to Maldraxxus?\n\nPerhaps research can divine the answer.", progress = "Let's see, where did that paper go?", completion = "This will be very helpful. It's a shame so many people aren't willing to share their knowledge. Hoarding it is simply foolish.", objectives = "Collect information on the kyrian from the Temple of Humility.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58518] = { id = 58518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Always a Paper Trail", description = "I noticed that you were surprised to find those strange weapons here.\n\nI sense the essence of their power as well. It is strangely familiar...\n\nWe must discover where the weapons came from and who imbued them with such power.\n\n<Kael'thas smiles.>\n\nIf you and I present the proof to the Accuser together, perhaps she shall allow us to hunt down whoever is behind all of this!", progress = "You found something?", completion = "A lich?! The Tithelord is working with a lich from Maldraxxus?!\n\nHow? To what ends?\n\n<The Accuser composes herself.>\n\nDo you appreciate how troubling this is, {name}?\n\nThis has never happened. This is not supposed to happen.\n\nPrince Renathal will know what to do.", objectives = "Discover proof of who's supplying the venthyr with Maldraxxian weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58523] = { id = 58523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Dead To Me", description = "Your cooperation is expected, but I await results.\n\nOur reconnaissance has revealed a Maldraxxi encampment in the Endmire. We speculate that your kind have been siphoning the Master's stockpiles of anima.\n\nI have called for a carriage to take us there. Let us make haste.", completion = "We have arrived. Let us not dally.", objectives = "Follow the Accuser to the Maldraxxi encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58524] = { id = 58524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparkles Rain from Above", description = "You found the heart of the grove! And it's full of anima!\n\nThe Drust don't seem to like the idea of you taking it from them. They're massing in great numbers all over the forest!\n\nWe need to get you and the others out of here safely.\n\nI can help. How do you feel about dishing out a little sparkly mayhem?", completion = "You found and took their anima right from the heart of the grove? Impressive.\n\nDreamweaver will be most pleased. But I expect that we will soon encounter some unhappy visitors.\n\nWe must move quickly to aid the spirit in this wildseed... before we are overrun.", objectives = "Speak with Lady Moonberry and escape Tirna Noch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58525] = { id = 58525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Two Sides of History", description = "You mortals always say that history is written by the victors. But in the Shadowlands, I have found that to be untrue.\n\nEveryone has their own version of events. I would like to know them all. \n\nThere was an author of history books who made her abode in Revendreth's  Darkfall Tower. She wrote from the venthyr's perspective of various incursions and battles alongside the Primus. \n\nIf we could find copies of her works...", completion = "You found them! What wonderful insight into the minds of the venthyr.", objectives = "Find copies of \"On Bone and Stone\" and \"The Malice of Maldraxxus.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58530] = { id = 58530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Mirror", description = "If Renathal is going to put the Harvesters' medallions to use, he's going to need a conduit to focus that power. Denathrius's corruption taints the forges of Revendreth. Our best option is in Bastion.\n\nAs denizens of Revendreth, Bastion will not allow us to enter through Oribos. \n\nWe will need you to activate a mirror hidden away there long ago. Take this.\n\nWe concealed it at a rarely used site, the Veiled Enclave. There should be no one there, especially with the drought.", completion = "It's been quite a while since I've seen these plains. \n\nI am surprised the illusion lasted as long as it did. It was concealed here many years ago for operations in the Master's name.\n\nNo matter, let us make haste. We are not here on a simple observation mission.", objectives = "Use Laurent's Compact Looking Glass to reveal the Hidden Mirror in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58555] = { id = 58555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tense Reunion", description = "We are looking for the forgelite prime, Mikanikos.\n\nOnly he will be able to craft the device we need. I've seen some of his creations. Truly impressive constructs and weaponry that rival even the mightiest of us stoneborn.  \n\nWhen last I encountered him, it was at his workshop. A place of wonders known as the Eternal Forge.\n\nWe will meet you there. Traveling as a group may draw too much attention.", completion = "Just let me do the talking. One wrong move and they will surely revoke this trust.\n\nNow is not the time for more bloodshed between realms.", objectives = "Meet General Draven and Theotar at the Eternal Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58557] = { id = 58557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assistance from Sinfall", description = "In order to defeat the Forsworn, the Crest needs an artifact that embodies repentance, atoning for past mistakes and moving forward.\n\nI have an artifact in mind. \n\nLong ago, many souls from Revendreth arrived in Bastion. Purer souls than we have ever received from Revendreth.\n\nThey bore the mark of the Seal of Contrition, a focus that expedited their cleansing.\n\nGo to Revendreth and find this seal so that we may harness its power.", completion = "I am truly sorry I do not have more answers... the Maw scattered my mind quite a bit.\n\nI will help to the best of my ability.", objectives = "Meet with The Curator in Darkhaven in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58558] = { id = 58558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overhead Intelligence", description = "The Countess knows the fates and goings-on of every noble in Revendreth. It is the best way to keep them in her debt.\n\nHowever, she has a dark secret. Despite what she may say... she was once mortal.\n\nWe will need to find where she keeps her sinstone. No easy feat, of course.\n\nWe will need to gather some intel. The venthyr of the Chalice District are constantly gossiping. Collect their letters from the couriers until you learn something of interest.", completion = "Three houses that find themselves in the Countess's favor... Peculiar.\n\nSounds like you are going to explore the Redelav District!", objectives = "Collect the Rumors of Favor from Chalice Couriers in the Chalice District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58559] = { id = 58559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Master", description = "I worry about entering the city. I'm sure you have noticed how well we... stand out here.\n\nDenathrius's loyalists have eyes everywhere, and no more dedicated soldiers than the stoneborn.\n\nTheir eyes and ears watch over the Chalice District. Take out their leaders so none can report our presence here before we acquire the seal.", progress = "The stoneborn forces can never be truly defeated, but they can be quelled for a time.", completion = "This city makes my skin crawl. I feel like I am constantly being watched, that people are whispering behind my back.\n\nTaking out the stoneborn leaders should slow the flow of information back to Denathrius's loyalists.", objectives = "Kill Evaala the All-Seeing, Guardian Mastrus, and Keraal the Ripper in the Chalice District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58560] = { id = 58560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gothic Fashion", description = "Making my way into the city unseen was not as simple as I thought.\n\nI trekked through some mud, where I came across these... small men.\n\nPerhaps Kleia is right. I draw far too much attention here to be of much use. \n\nPerhaps I can disguise myself? Please, help me by gathering some venthyr clothing as a disguise.", completion = "<Pelagos sifts through the clothing you brought him.>\n\nSuch fine fabric... I believe this could work!", objectives = "Collect 5 articles of venthyr clothing from Chalice Residents and Garment Trunks in the Chalice District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58561] = { id = 58561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of the Countess", description = "The venthyr travel long distances through enchanted mirrors. The keys we look for are not as we have in Bastion, but rather shards of a mirror that will lead to the sinstone's location.\n\nBased on the intel you found, we know which three houses hold these shards.\n\nPrimrose, Darkvein, and Sinfang.\n\nGo to their manors and retrieve the shards. We will find the frame to piece them into.", completion = "I am sure you caused quite a ruckus amongst the nobility. We must work quickly.", objectives = "Collect the 3 Shards of the Countess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58562] = { id = 58562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Dust", description = "If I know the Countess, which I do, her sinstone will have stronger protection than mere keys.\n\nShe is quite fond of curses to protect her gateways. I am capable of creating a residue that should protect us, but it requires the petals of a specific flower you can find in Redelav gardens.\n\nCollect the petals of these flowers so that I may protect us from the dangers to come.", progress = "I will need many petals to protect the four of us.", completion = "<The Curator sifts through the petals.>\n\nIt may be a stretch, but I believe I can make this work.", objectives = "Collect 30 Death Lotus Petals from Death Lotuses in the Redelav District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58563] = { id = 58563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Glass", description = "The mirror frame rests at the bottom of Redelav Hall. Kleia and Pelagos wait there.\n\nWith these shards, I can piece it together.\n\nWe will go through, grab the sinstone, and go face the Countess. Let nothing stand in our way.", progress = "Venthyr carry their pasts as a burden, a weight upon them.\n\nThe kyrian stand free of ours.", completion = "So much power in one stone.\n\nYour past can be used against you. This is why we free ourselves.", objectives = "Go through the mirror, then collect the Countess's Sinstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58564] = { id = 58564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Past", description = "The Countess built her reputation on being a native venthyr, never a soul.\n\nRevealing her sinstone to the world would be catastrophic. This is the leverage we need for the information we seek.\n\nShe will tell us where Alwin is. Where the seal is.\n\nThis mirror leads to her estate. I will follow behind you as backup, but the kyrian shall wait here.\n\nDon't let her threaten you. You hold the power.", progress = "You are lucky that the Curator is by your side, Maw Walker.\n\nIf you dared this stunt on your own, you would never see your precious Bastion again.", completion = "I shall tell you the story of the Seal of Contrition.\n\nThen you are to leave. Immediately.", objectives = "Go through the mirror and face the Countess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58565] = { id = 58565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land of Light", description = "The Ember Ward is filled with outcasts from Revendreth society, whether they rebelled, crossed a noble, or simply looked at Denathrius wrong.\n\nIt is a Light-scorched land that drives venthyr mad, unless they manage to stay within the shadows.\n\nIf Alwin is there, it may be too late.\n\nLet us visit Theotar at the Sanctuary of the Mad. I'm sure he will be pleased to see you.", completion = "Ah, {name}, welcome back to Revendreth!\n\nAllow me to connect you with someone who may be of service.", objectives = "Meet Theotar at the Sanctuary of the Mad in the Ember Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58566] = { id = 58566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Actions Speak Louder than Words", description = "<The ash ghoul inspects you, checking your weapons and armor closely.\n\nHe shifts his eyes from you to your kyrian companions before checking back in with Theotar, who nods to him.\n\nAlwin motions for you to follow him.>", completion = "<Alwin looks to you, then to Kleia.\n\nHe nods, resolve in his eyes.>", objectives = "Follow Mindscorched Alwin through the Ashen Traverse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58567] = { id = 58567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulking in the Darkness", description = "I had only heard tales of the Ember Ward before now.\n\nIt's breathtaking... yet terrible.\n\nThe Light burns the venthyr here, scorching their flesh and driving them mad.\n\nThe only reprieve is darkness, but thugs have taken over every inch of shelter outside of this sanctuary.\n\nThere is no redemption for them. Only justice.", completion = "When people fall to their vices, they must be judged accordingly.", objectives = "Kill 8 outcast venthyr in the Ashen Traverse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58568] = { id = 58568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Respite", description = "We passed many ash ghouls on the way here, screaming in pain from their Light-dispensed burns.\n\nAnd after meeting Alwin and the others here, my heart aches for them.\n\nThey have lost much of who they once were, and suffer daily for it.\n\nPlease, collect some berries from the Ashen Traverse. I believe I could impart anima into them to create a healing salve to soothe their wounds.\n\nIt is the least I can do.", progress = "The denizens of the Ember Ward have suffered enough for their mistakes.\n\nThe Light goes too far in its punishment.", completion = "It is my duty to help those in pain. This salve shall help.", objectives = "Collect 25 Brushberries from the Ashen Traverse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58569] = { id = 58569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Folly of Envy", description = "<Alwin points at a venthyr on the ledge above.\n\nHe lets out a slight, low rumble.>", progress = "Alwin has brought us far. We must retrieve the Seal!", completion = "Could it really be? The object of our long search...", objectives = "Kill Duke Vielle and retrieve the Seal of Contrition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58570] = { id = 58570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Words", description = "With the seal in hand, we must return to Bastion.\n\nAlwin has received his justice. He has bequeathed the seal to our care.\n\nLet us say our goodbyes at the Sanctuary of the Mad, then head home.\n\nI look forward to returning to the blue skies and open fields of Bastion.", progress = "You return! With good news, I hope?", completion = "Concern about Kalisthene's report... but not my problem! Seal should work perfectly.", objectives = "Speak to the Curator at Sanctuary of the Mad, then return to Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58571] = { id = 58571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seal of Contrition", description = "Preparations for the Seal are complete.\n\nGo, insert it into the Crest. Be delicate, yet firm! Move with purpose, but a steady hand.", progress = "<The orb hangs in front of you. The Seal in your hand pulses quickly.>", completion = "<You see the Seal of Contrition flash with power as you pull your hand away from it.\n\nOne singular item, connecting the denizens of Bastion and Revendreth in more ways than the obvious.>", objectives = "Place the Seal of Contrition in the Crest of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58575] = { id = 58575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stuff We All Get", description = "A lot of competitors meet their end in the Theater of Pain. But their weapons are still good as new!\n\nIt can get expensive to equip a fresh recruit, especially if you're not sure they'll survive their first bout. That's why we outfit them with \"slightly used\" armaments.\n\nGather them up for me, would you? Can't let a good weapon go to waste!", progress = "The weapons you collect could be wielded by a future champion!", completion = "These weapons will be put to good use. Hopefully, we won't have to collect some of them again.", objectives = "Collect 12 Weapons of the Fallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58582] = { id = 58582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Black Prince", description = "<The envelope contains a message from Valeera Sanguinar.>\n\n{name},\n\nI have just returned from a meeting with King Wrynn in Stormwind.\n\nWe have much to discuss.\n\nMeet me at the Great Seal with haste.\n\nAl diel shala,\nValeera", progress = "Yes?", completion = "I hope that Wrathion's expertise can lead us to the Old God.\n\nWe have precious little else to go on otherwise.", objectives = "Speak with Valeera Sanguinar at the Great Seal in Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58583] = { id = 58583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Heart Is", description = "The Speaker has requested that I send you to aid him and Wrathion in their efforts.\n\nYou have proven yourself a great ally to Azeroth, and I suspect you will have a big part to play in the coming battles.\n\nLet us hope that the rest of the Horde and Alliance can put aside their squabbles to face a common enemy.", completion = "Ah, ye made it! An' just in time!\n\nWrathion's got a plan on how we might be able tae outmaneuver N'Zoth. When the Old God shows his face though, we're gonna need ye tae take the hurt to 'em!\n\nLet's get started!", objectives = "Meet Magni Bronzebeard in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58584] = { id = 58584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right our Wrongs", description = "General Kaal was sent here on a mission for Denathrius long ago.\n\nOn that mission, they concealed anima siphons, making their presence impossible to detect, to limit the amount of anima this workshop could use. That destabilized this area. The Forsworn must have noticed this and exploited the weakness.\n\nThese previous actions are in opposition to our goal. Take Theotar and destroy those siphons.", completion = "The job is done. \n\nThis should allow the anima to return. \n\nYour dedication to our cause is great. I cannot think of one more fitting to wear this cloak.", objectives = "Speak to Theotar at the Eternal Forge. Then, reveal and destroy 5 Concealed Anima Siphons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58585] = { id = 58585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Friend of Mine", description = "Tools. I cannot work without my tools!\n\nFamos, my former apprentice, stole them all when she went to the Forsworn.\n\nIt breaks my heart. She had so much promise.\n\nShe must be stopped.", progress = "I need my tools. My work cannot be done without them.", completion = "My tools. At least Famos took care of them.", objectives = "Kill Famos in the Eternal Forge and collect Mikanikos's Toolchest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58586] = { id = 58586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Stuff", description = "Building something that can help in your mission will require some metal.\n\nThe constructs of the Forsworn have metal parts, suitable for what we need. Tainted by the Forsworn, they will need some additional work.\n\nCollect their metal and smelt them in the flames of the Eternal Forge to purge the corruption.", progress = "Do you have the metal?", completion = "Metal will do. Good work.", objectives = "Kill Forsworn constructs and collect and smelt 5 Tainted Centurion Components.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58589] = { id = 58589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Dreamer", description = "Now that we have the anima we need, we must attune the heart of Tirna Noch to the shrines of Hibernal Hollow. \n\nThen we can bring the wildseed's nightmares into the light and dispel them.\n\nTake the heart to the shrines just outside of Hibernal Hollow, in the Dreamshrine basin. Then bring the heart back to the wildseed to complete the preparations for the ritual.\n\nBut be careful. Minions of the Drust seem to be amassing near the grove.", progress = "The spirit dreams.", completion = "You're a natural at this. Now we can bring the spirit's nightmares into the open and deal with them directly.\n\nIf we succeed, she will be so much more at peace.", objectives = "Attune the filled heart of the tree at the shrines in the Dreamshrine Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58590] = { id = 58590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Dreamer: Origins", description = "The spirit within the wildseed dreams of her birth and youth, in the primordial days of her world.\n\nGo to the first Dreamshrine outside of Hibernal Hollow. Meditate at the shrine, and soothe this vision of how her life began.", completion = "We all start somewhere. Sometimes in unexpected places. Me, I just popped out of the ground like a flower.", objectives = "Grapple with the spirit's vision of their origin.\n\nIf you leave the Vision, interact with a Dreamer's Vision portal in Dreamshrine Basin to enter again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58591] = { id = 58591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Despoilers", description = "Your efforts at Tirna Noch have enraged the Drust. \n\nThose creatures of decay and destruction swell at our borders, and already they pierce our defenses.\n\nNow we see their real faces, and know the true nature of our foe.\n\nStrike at them. It will buy us time for you to conduct Dreamweaver's ritual.", completion = "This is just the beginning of their attack. But it is still a heavy blow dealt to them. Thank you.", objectives = "Slay Witherscorn Drust and Blighted, and vanquish Skell the Despoiler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58592] = { id = 58592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caring for the Caretakers", description = "The Drust attacked so quickly, they captured some of the spirit tenders of this grove!\n\nIt's not an easy job to do, between the drought and monsters and everything. I should know.\n\nPlease, see if you can get them out of whatever terrible magic those invaders have cast on them.", completion = "Those Drust really are cruel to us fae! Those spirit tenders were just trying to do their job...\n\nThank you for helping them.", objectives = "Free Spirit Tenders in the Dreamshrine Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58593] = { id = 58593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Dream", description = "The time has come. The ritual will be complete when you have fully entered into the spirit's dreams.\n\nIt will be as if you are her, in every aspect.\n\nShe relives the moment of her death over and over again. It torments her. Something about how she ended... she had no control over her actions. She hurt the ones she loved.\n\nSpeak to me when you are ready to immerse yourself in her nightmare of the end.", progress = "Have you entered into the spirit's final dream and witnessed her fate?", completion = "What a terrible end for such a majestic spirit... \n\nBut that was why she connected with you! Because you are of the same world! Azeroth!\n\nNow, I can finally feel her nightmares wane. At last, she knows some peace.\n\nThank you, my friend.", objectives = "Witness the end of the spirit's life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58595] = { id = 58595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pillars of Oblivion", description = "In ages past, the black obelisks of the Old Gods would herald the coming of their forces. The dark conjurers among the k'thir and n'raqi would utilize these monuments to establish footholds in our world and usher in more of the Old Gods' minions.\n\nToday, we see these very same obelisks littering the battlefields. So long as they stand, N'Zoth's forces will be without end.\n\nMake sure they do not.", progress = "Is your task complete?", completion = "You've destroyed the obelisks? Good, the Old Gods must be given no ground.\n\nRemember this in your battles.", objectives = "Destroy 6 Black Empire Obelisks in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58596] = { id = 58596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Specter Of War: Visectus" }
quests[58599] = { id = 58599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive A Dredge Between Them", description = "First, we ruin their operation. Questions can come later.\n\nI scouted from the overlook as we rode in. Necromancers charge crystals full of siphoned anima. Three dredgers stack them onto carts.\n\nKill those dredgers and everything will grind to a halt.", progress = "Are you ready?", completion = "Well done.", objectives = "Kill the 3 large dredgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58600] = { id = 58600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Circle", description = "I've come up with the perfect design to fit your needs--a crown capable of channeling the powers of the Harvesters.\n\nI need one more tool to put it together, a mold. Circular objects difficult to get right.\n\nGo up to my old storage. A perfect mold exists there. I'm sure of it.\n\nPerhaps in one of my old trunks. Go rummage around for it, will you?", progress = "Crown must be perfect!", completion = "Perfectly crafted. Just what we need.", objectives = "Search for the Perfected Circlet Mold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58601] = { id = 58601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Web of Information" }
quests[58603] = { id = 58603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phaestus, Genesis of Aeons", description = "Missing something sacred.\n\nForsworn ransacked our shrine to the First Forgelite and took her hammer. My hammer!\n\nDefeat their commander, retrieve Phaestus. You must go now!", progress = "Without Phaestus, we cannot forge your crown!", completion = "Phaestus returns! Glorious day.\n\nMany thanks, friend. This hammer has been passed down for eons! It belongs in my masterful hands.", objectives = "Collect Phaestus, Genesis of Aeons from Overseer Atticus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58605] = { id = 58605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateur Night" }
quests[58606] = { id = 58606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of Investigation", progress = "Have you managed to acquire the samples?", completion = "Marvelous! Your contributions to the League will be duly noted.", objectives = "Collect 16 Aqir Bits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58608] = { id = 58608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Treason, Then", description = "We've halted their efforts, but we still have more to do.\n\nSin'dane must have sent someone to oversee the encampment.\n\nFind and slay whoever is in charge. Only then can we be sure their work has ended.", progress = "Still more schemes...", completion = "The Banished One... The Pauldrons of Imperium...\n\nThis lich, Kel'Thuzad, meddles with powerful forces.", objectives = "Kill Lady Ouix'ara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58609] = { id = 58609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking The Seat", description = "A wise choice, {name}. Under your command, we will restore honor and glory to Maldraxxus.\n\nYour strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential.\n\nFor now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.", completion = "Welcome back to the fight, {name}.", objectives = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58610] = { id = 58610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker of Elune", description = "Fortune smiles upon us, {name}. We have found a soul in Ardenweald who was once a Night Warrior in life, as Tyrande is now. \n\nHis name is Thiernax. I am told he assists in tending to the spirits resting in the Garden of Night.\n\nSeek him out and petition him for aid. I pray he will have wisdom to share.", progress = "Oh, dear.", completion = "<Qadarin watches Thiernax race off. He sighs before turning to you.>\n\nMy apologies. Thiernax may have seemed curt, but there is a reason for his reluctance to speak of the Night Warrior.\n\nIf you have a moment to help me out in the garden, I can elaborate. Then I will see what can be done to convince Thiernax to help your mother.", objectives = "Find Thiernax near the Queen's Garden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58615] = { id = 58615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers in the Dark", description = "Did ye hear that as well? That cannae be good.\n\nIf N'Zoth gains access tae this chamber, we'll all be done for! \n\nWe need tae figure out where he's accessing the chamber and shut it down, before he does more than just whisper at us!", completion = "What have we done?\n\nIf it weren't for Ra-den's sacrifice, N'Zoth would've had the chamber, and Azeroth would've been his for the takin'.", objectives = "Find the source of N'Zoth's whispers in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58616] = { id = 58616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging a Champion", description = "Of all the souls who have reached that stone, only you discovered its true purpose.\n\nI am no zealot, but clearly there is a deeper meaning in this. We would be wise to investigate further.\n\nFind Bonesmith Heirmir at her forge. She is the most renowned smith in Maldraxxus, and the last remaining apprentice of the Primus himself.\n\nShe will know what course to take.", progress = "Something else?", completion = "This is going to take a bit of work.", objectives = "Speak with Bonesmith Heirmir about your runeblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58617] = { id = 58617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining Order", description = "Communication is the key to victory. The greatest strategists are rendered useless if their orders go unheard.\n\nDeliver my orders to Summoner Perex, Drill Sergeant Telice, and Secutor Mevix.\n\nAnd do it quickly. Every moment we waste is one our enemy will have to their advantage!", completion = "That should ensure we stand ready for war.", objectives = "Deliver orders to Summoner Perex, Drill Sergeant Telice, and Secutor Mevix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58618] = { id = 58618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ossein Enchantment", description = "A potent blade requires potent components. I know of something that would suit our needs.\n\nRecently a monstrosity trained by the constructs was snared by our soldiers at the eastern side of our stronghold. Vyraz insists we can siphon \"intelligence\" from the beast's mind.\n\nHmph. The will of the Primus trumps the desires of an ambitious baron!\n\nThe bones of that beast would forge the perfect hilt for this blade. I say you lay claim to them.", progress = "Brave enough to manage this?", completion = "Good! I knew that beast would prove no challenge for you.", objectives = "Slay Marrowjaw and collect an Empowered Bone from its corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58619] = { id = 58619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Read Between the Lines", description = "Ah, mortal, how fortunate that I, humble Ta'eran, happen to be standing here just as you, the outsider everyone is talking about, happens to wander by!\n\nIn the spirit of cooperation and mutual interests, there is a matter I wish to discuss.\n\nA nearby structure called the Sepulcher of Knowledge was built as a repository for military strategy. I fear the knowledge contained within may soon be lost.\n\nIf you would do me the honor of escorting me to the Sepulcher, I can share what else I know.", completion = "Mortal, are you ready to help me save these valuable writings?", objectives = "Follow Ta'eran to the Sepulcher of Knowledge and hear his proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58620] = { id = 58620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaylines", description = "Gaining entrance to the Sepulcher is no easy feat, {name}!\n\nNot only were guardians put in place, but an elaborate magical lock was created to seal the door. \n\nTo open the way, the two obelisks which control the lock must be fed anima. Fortunately, there are some empowered crystals in the area we can use for this purpose.\n\nLocate the focus crystals and redirect their anima flow into the obelisks. Then the secrets of the Sepulcher will soon be ours!", progress = "Have you activated the two obelisks?", completion = "You have done it! The door is unlocked!", objectives = "Connect the anima flow to the Unlocking Obelisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58621] = { id = 58621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repeat After Me", description = "The Primus placed guardians in the area around the Sepulcher to protect the knowledge within. Each embodied the virtues of one of the five houses.\n\nTo gain entrance, you must prove yourself worthy by besting these protectors. \n\nSeek out the rune stones that represent the houses of Maldraxxus. Pay attention to the words inscribed on each stone, then pay deference each house's values.\n\nIf you honor the stone, its protector will come forth. Defeat each of them.", progress = "The Primus was clever indeed.", completion = "Now that those guardians are dispatched, we can focus on unlocking the door.", objectives = "Read the rune stones of the five houses, then honor them by performing the correct /emote at each stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58622] = { id = 58622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets Among the Shelves", description = "Now that the door to the Sepulcher is unlocked, we can venture inside.\n\nAnd by \"we\", I mean \"you\". Until it's safe, at least.\n\nThe volumes within contain the collected wisdom of the greatest military minds of Maldraxxus. For the good of the Necrolords, do whatever is needed to gather these precious volumes.\n\nIt is safe to assume that the books will be protected by traps. The Primus wouldn't want just anyone laying their hands on this knowledge.\n\nOnce you clear a path, I'll join you.", progress = "Were you successful?", completion = "Fine work so far.\n\nAccess to the secret archives is almost ours!", objectives = "Recover volumes of the tomes kept within the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58623] = { id = 58623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Complete Set", description = "This is only volume one?\n\nWe can't just take the first volume. A rare item like this is only useful if it's in a complete set!\n\nGrab as many of the other volumes as you can, I will have to prepare a larger expedition to remove all of these volumes.", progress = "Did we get all the volumes?", completion = "So much valuable knowledge saved, and it would not have happened without your help.", objectives = "Collect Volumes of Victory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58624] = { id = 58624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pauldrons of Imperium", description = "Now we know who is responsible for the unrest in Maldraxxus.\n\nIf Kel'Thuzad has allied with the Banished One, then he wields greater power than anyone realizes. \n\nWe must lay siege to the House of Rituals, but we need time to prepare. Attacking without a flawless strategy will only ensure our defeat.\n\nFor now, return the pauldrons to the Seat of the Primus. I will meet you there.", completion = "The battle has only just begun.", objectives = "Return to the Seat of the Primus with the Pauldrons of Imperium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58625] = { id = 58625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Connecting the Dots", description = "The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting.\n\nHe went off to meet with some member of the House of Rituals. There were a few of his guards with him.\n\nWhile it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.", objectives = "Search the Forgotten Wounds for the previous baron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
